#include <filesystem>
#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

#include "endpoint.h"
#include "json.h"
#include "tsv.h"

class protocol_map {
public:
	enum class observe_mode {
		all,
		configured_only,
		configured_plus_other,
	};

	struct vlan_match {
		enum class mode {
			any,
			untagged,
			id,
		};

		mode type{mode::any};
		std::string id;
	};

	struct rule {
		std::string proto;
		std::vector<std::string> endpoints;
		std::vector<std::string> hosts;
		std::vector<std::string> decode_as;
		bool fec{false};
		bool observe{true};
		vlan_match vlan;
	};

	int load(const std::filesystem::path &path);

	const std::vector<rule>& rules() const noexcept { return m_rules; }
	const std::vector<std::string>& decode_as_rules() const noexcept { return m_decode_as_rules; }
	observe_mode observation_mode() const noexcept { return m_observe_mode; }
	bool should_observe(std::string_view proto, const ip_endpoint &src, const ip_endpoint &dst, const tsv::vlan_info &vlan, std::string_view host = {}) const;
	bool has_observable_host_rule(std::string_view proto, const tsv::vlan_info &vlan) const;
	const std::vector<ip_endpoint>& rtp_fec_base_endpoints() const noexcept { return m_rtp_fec_base_endpoints; }
	bool empty() const noexcept { return m_rules.empty(); }

private:
	observe_mode m_observe_mode{observe_mode::all};
	std::vector<rule> m_rules;
	std::vector<std::string> m_decode_as_rules;
	std::vector<ip_endpoint> m_rtp_fec_base_endpoints;

	static std::vector<std::string> read_string_or_array(const json &j, const char *key);
	static bool read_bool(const json &j, const char *key, bool fallback);
	static observe_mode read_observe_mode(const json &j);
	static vlan_match read_vlan_match(const json &j);
	static bool endpoint_port(const std::string &endpoint, unsigned &port);
	static bool parse_endpoint(const std::string &endpoint, ip_endpoint &out);
	static bool auto_decode_as(std::string_view proto, unsigned port, std::string &out);
	static bool proto_matches(std::string_view rule_proto, std::string_view observed_proto);
	static bool is_dedicated_proto(std::string_view proto);
	static bool vlan_matches(const vlan_match &rule_vlan, const tsv::vlan_info &packet_vlan);
	static bool endpoint_matches(const rule &r, const ip_endpoint &candidate);
	static bool endpoint_matches(const rule &r, const ip_endpoint &configured, const ip_endpoint &candidate);
	static bool host_matches(const rule &r, std::string_view host);
	void add_decode_as(std::string value);
};

#endif /* PROTOCOL_MAP_H */
