#include <iostream>
#include <string_view>

namespace {

std::string upper(std::string_view value) {
	std::string out;
	out.reserve(value.size());
	for(unsigned char ch : value) {
		out.push_back(static_cast<char>(std::toupper(ch)));
	}
	return out;
}

std::string lower_host(std::string_view value) {
	std::string out;
	out.reserve(value.size());
	for(unsigned char ch : value) {
		out.push_back(static_cast<char>(std::tolower(ch)));
	}

	if(!out.empty() && out.back() == '.') {
		out.pop_back();
	}

	if(!out.empty() && out.front() == '[') {
		const auto close = out.find(']');
		if(close != std::string::npos) {
			return out.substr(1, close - 1);
		}
	}

	const auto colon = out.rfind(':');
	if(colon != std::string::npos && out.find(':') == colon) {
		bool numeric_port = colon + 1 < out.size();
		for(std::size_t i = colon + 1; i < out.size() && numeric_port; ++i) {
			numeric_port = std::isdigit(static_cast<unsigned char>(out[i]));
		}
		if(numeric_port) {
			out.resize(colon);
		}
	}

	return out;
}

bool is_tls_proto(std::string_view value) {
	const std::string p = upper(value);
	return p == "TLS" || p.rfind("TLSV", 0) == 0 || p == "SSL";
}

} // namespace

int protocol_map::load(const std::filesystem::path &path) {
	m_observe_mode = observe_mode::all;
	m_rules.clear();
	m_decode_as_rules.clear();
	m_rtp_fec_base_endpoints.clear();

	if(path.empty()) {
		return 0;
	}

	std::ifstream in(path);
	if(!in) {
		std::cerr << "protocol_map: failed to open " << path << std::endl;
		return -1;
	}

	json root;
	try {
		in >> root;
	}
	catch(const std::exception &e) {
		std::cerr << "protocol_map: failed to parse " << path << ": " << e.what() << std::endl;
		return -1;
	}

	m_observe_mode = read_observe_mode(root);

	if(!root.is_object() || !root.contains("protocols") || !root["protocols"].is_array()) {
		std::cerr << "protocol_map: root.protocols must be an array" << std::endl;
		return -1;
	}

	for(const auto &entry : root["protocols"]) {
		if(!entry.is_object()) {
			std::cerr << "protocol_map: protocol entry must be an object" << std::endl;
			return -1;
		}
		if(!entry.contains("proto") || !entry["proto"].is_string()) {
			std::cerr << "protocol_map: protocol entry requires string proto" << std::endl;
			return -1;
		}

		rule r;
		r.proto = entry["proto"].get<std::string>();
		r.endpoints = read_string_or_array(entry, "endpoints");
		r.hosts = read_string_or_array(entry, "hosts");
		{
			auto domains = read_string_or_array(entry, "domains");
			r.hosts.insert(r.hosts.end(), domains.begin(), domains.end());
		}
		r.decode_as = read_string_or_array(entry, "decode_as");
		r.fec = read_bool(entry, "fec", false);
		r.observe = read_bool(entry, "observe", true);
		r.vlan = read_vlan_match(entry);

		for(const auto &decode : r.decode_as) {
			add_decode_as(decode);
		}

		if(r.decode_as.empty()) {
			for(const auto &endpoint : r.endpoints) {
				unsigned port = 0;
				if(!endpoint_port(endpoint, port)) {
					std::cerr << "protocol_map: invalid endpoint " << endpoint << std::endl;
					return -1;
				}

				const bool expand_rtp_fec = upper(r.proto) == "RTP" && r.fec;
				const unsigned decode_count = expand_rtp_fec ? 3U : 1U;
				for(unsigned n = 0; n < decode_count; ++n) {
					const unsigned decode_port = port + n * 2U;
					if(decode_port > 65535U) {
						std::cerr << "protocol_map: RTP FEC endpoint port overflow " << endpoint << std::endl;
						return -1;
					}

					std::string decode;
					if(auto_decode_as(r.proto, decode_port, decode)) {
						add_decode_as(std::move(decode));
					}
					else {
						std::cerr << "protocol_map: no auto decode-as rule for proto "
						          << r.proto << " endpoint " << endpoint << std::endl;
						return -1;
					}
				}
			}
		}

		if(upper(r.proto) == "RTP" && r.fec) {
			for(const auto &endpoint : r.endpoints) {
				ip_endpoint base{};
				if(!parse_endpoint(endpoint, base)) {
					std::cerr << "protocol_map: invalid RTP FEC base endpoint " << endpoint << std::endl;
					return -1;
				}
				m_rtp_fec_base_endpoints.push_back(base);
			}
		}

		m_rules.push_back(std::move(r));
	}

	return 0;
}


protocol_map::observe_mode protocol_map::read_observe_mode(const json &j) {
	if(!j.is_object() || !j.contains("observe_mode") || j["observe_mode"].is_null()) {
		return observe_mode::all;
	}
	if(!j["observe_mode"].is_string()) {
		std::cerr << "protocol_map: observe_mode must be a string" << std::endl;
		return observe_mode::all;
	}

	const std::string mode = upper(j["observe_mode"].get<std::string>());
	if(mode == "ALL") {
		return observe_mode::all;
	}
	if(mode == "CONFIGURED_ONLY") {
		return observe_mode::configured_only;
	}
	if(mode == "CONFIGURED_PLUS_OTHER") {
		return observe_mode::configured_plus_other;
	}

	std::cerr << "protocol_map: unknown observe_mode " << j["observe_mode"].get<std::string>()
	          << ", fallback to all" << std::endl;
	return observe_mode::all;
}

protocol_map::vlan_match protocol_map::read_vlan_match(const json &j) {
	vlan_match out{};
	if(!j.is_object() || !j.contains("vlan")) {
		return out;
	}

	const auto &value = j["vlan"];
	if(value.is_null()) {
		out.type = vlan_match::mode::untagged;
		return out;
	}
	if(value.is_number_integer()) {
		const auto id = value.get<int>();
		if(id < 0) {
			std::cerr << "protocol_map: vlan must not be negative; fallback to any" << std::endl;
			return out;
		}
		out.type = vlan_match::mode::id;
		out.id = std::to_string(id);
		return out;
	}
	if(value.is_number_unsigned()) {
		out.type = vlan_match::mode::id;
		out.id = std::to_string(value.get<unsigned>());
		return out;
	}
	if(value.is_string()) {
		out.type = vlan_match::mode::id;
		out.id = value.get<std::string>();
		return out;
	}

	std::cerr << "protocol_map: vlan must be null, number, or string; fallback to any" << std::endl;
	return out;
}

std::vector<std::string> protocol_map::read_string_or_array(const json &j, const char *key) {
	std::vector<std::string> out;
	if(!j.contains(key) || j[key].is_null()) {
		return out;
	}

	const auto &value = j[key];
	if(value.is_string()) {
		out.push_back(value.get<std::string>());
		return out;
	}
	if(value.is_array()) {
		for(const auto &item : value) {
			if(item.is_string()) {
				out.push_back(item.get<std::string>());
			}
		}
	}
	return out;
}

bool protocol_map::read_bool(const json &j, const char *key, bool fallback) {
	if(!j.contains(key) || !j[key].is_boolean()) {
		return fallback;
	}
	return j[key].get<bool>();
}

bool protocol_map::endpoint_port(const std::string &endpoint, unsigned &port) {
	const auto pos = endpoint.rfind(':');
	if(pos == std::string::npos || pos + 1 >= endpoint.size()) {
		return false;
	}

	unsigned value = 0;
	for(std::size_t i = pos + 1; i < endpoint.size(); ++i) {
		unsigned char ch = static_cast<unsigned char>(endpoint[i]);
		if(!std::isdigit(ch)) {
			return false;
		}
		value = value * 10U + static_cast<unsigned>(ch - '0');
		if(value > 65535U) {
			return false;
		}
	}

	port = value;
	return true;
}

bool protocol_map::parse_endpoint(const std::string &endpoint, ip_endpoint &out) {
	unsigned port = 0;
	if(!endpoint_port(endpoint, port)) {
		return false;
	}

	std::string host;
	if(!endpoint.empty() && endpoint.front() == '[') {
		const auto close = endpoint.find(']');
		if(close == std::string::npos || close + 1 >= endpoint.size() || endpoint[close + 1] != ':') {
			return false;
		}
		host = endpoint.substr(1, close - 1);
	}
	else {
		const auto pos = endpoint.rfind(':');
		if(pos == std::string::npos || endpoint.find(':') != pos) {
			return false;
		}
		host = endpoint.substr(0, pos);
	}

	ip_addr addr{};
	if(!parse_ip(host, addr)) {
		return false;
	}
	out = ip_endpoint{addr, static_cast<std::uint16_t>(port)};
	return true;
}

bool protocol_map::auto_decode_as(std::string_view proto, unsigned port, std::string &out) {
	const std::string p = upper(proto);
	if(p == "SRT") {
		out = "udp.port==" + std::to_string(port) + ",srt";
		return true;
	}
	if(p == "RTP") {
		out = "udp.port==" + std::to_string(port) + ",rtp";
		return true;
	}
	if(p == "RTMP") {
		out = "tcp.port==" + std::to_string(port) + ",rtmpt";
		return true;
	}
	if(p == "HTTP" || p == "HLS") {
		out = "tcp.port==" + std::to_string(port) + ",http";
		return true;
	}
	return false;
}

void protocol_map::add_decode_as(std::string value) {
	if(value.empty()) {
		return;
	}
	if(std::find(m_decode_as_rules.begin(), m_decode_as_rules.end(), value) != m_decode_as_rules.end()) {
		return;
	}
	m_decode_as_rules.push_back(std::move(value));
}


bool protocol_map::proto_matches(std::string_view rule_proto, std::string_view observed_proto) {
	const std::string rule = upper(rule_proto);
	const std::string observed = upper(observed_proto);
	if(rule == observed) {
		return true;
	}
	return (rule == "HLS" && observed == "HTTP") ||
	       (rule == "HTTP" && observed == "HLS") ||
	       ((rule == "HLS" || rule == "HTTP") && is_tls_proto(observed_proto)) ||
	       (rule == "RTMP" && observed == "RTMPT") ||
	       (rule == "RTMPT" && observed == "RTMP");
}

bool protocol_map::is_dedicated_proto(std::string_view proto) {
	const std::string p = upper(proto);
	return p == "RTP" || p == "SRT" || p == "HTTP" || p == "HLS" || p == "RTMP" || p == "RTMPT";
}

bool protocol_map::vlan_matches(const vlan_match &rule_vlan, const tsv::vlan_info &packet_vlan) {
	switch(rule_vlan.type) {
	case vlan_match::mode::any:
		return true;
	case vlan_match::mode::untagged:
		return packet_vlan.empty();
	case vlan_match::mode::id:
		return packet_vlan.id == rule_vlan.id;
	}
	return false;
}

bool protocol_map::endpoint_matches(const rule &r, const ip_endpoint &configured, const ip_endpoint &candidate) {
	if(configured.addr == candidate.addr && configured.port == candidate.port) {
		return true;
	}

	if(!(upper(r.proto) == "RTP" && r.fec)) {
		return false;
	}
	if(!(configured.addr == candidate.addr)) {
		return false;
	}
	if(candidate.port < configured.port) {
		return false;
	}

	const auto offset = static_cast<unsigned>(candidate.port - configured.port);
	return offset == 2U || offset == 4U;
}

bool protocol_map::endpoint_matches(const rule &r, const ip_endpoint &candidate) {
	for(const auto &endpoint : r.endpoints) {
		ip_endpoint configured{};
		if(!parse_endpoint(endpoint, configured)) {
			continue;
		}
		if(endpoint_matches(r, configured, candidate)) {
			return true;
		}
	}
	return false;
}

bool protocol_map::host_matches(const rule &r, std::string_view host) {
	if(host.empty()) {
		return false;
	}

	const auto observed = lower_host(host);
	if(observed.empty()) {
		return false;
	}

	for(const auto &configured_host : r.hosts) {
		const auto configured = lower_host(configured_host);
		if(configured.empty()) {
			continue;
		}
		if(configured == observed) {
			return true;
		}
		if(configured.size() > 2 && configured[0] == '*' && configured[1] == '.') {
			const auto suffix = configured.substr(1);
			if(observed.size() >= suffix.size() &&
			   observed.compare(observed.size() - suffix.size(), suffix.size(), suffix) == 0) {
				return true;
			}
		}
	}

	return false;
}

bool protocol_map::should_observe(std::string_view proto,
                                  const ip_endpoint &src,
                                  const ip_endpoint &dst,
                                  const tsv::vlan_info &vlan,
                                  std::string_view host) const {
	if(m_observe_mode == observe_mode::all) {
		return true;
	}
	if(m_observe_mode == observe_mode::configured_plus_other && !is_dedicated_proto(proto)) {
		return true;
	}

	for(const auto &r : m_rules) {
		if(!r.observe) {
			continue;
		}
		if(!proto_matches(r.proto, proto)) {
			continue;
		}
		if(!vlan_matches(r.vlan, vlan)) {
			continue;
		}
		if(endpoint_matches(r, src) || endpoint_matches(r, dst) || host_matches(r, host)) {
			return true;
		}
	}

	return false;
}


bool protocol_map::has_observable_host_rule(std::string_view proto, const tsv::vlan_info &vlan) const {
	for(const auto &r : m_rules) {
		if(!r.observe || r.hosts.empty()) {
			continue;
		}
		if(!proto_matches(r.proto, proto)) {
			continue;
		}
		if(!vlan_matches(r.vlan, vlan)) {
			continue;
		}
		return true;
	}
	return false;
}
#ifndef PROTOCOL_MAP_H
