};

export function MaintenancePane({ refreshToken, onApplied }: MaintenancePaneProps) {
  const [settings, setSettings] = useState<MaintenanceSettingsResponse | null>(null);
  const [draft, setDraft] = useState<AppConfig | null>(null);
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");

  useEffect(() => {
    let cancelled = false;
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      if (cancelled) return;
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      if (cancelled) return;
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
    return () => { cancelled = true; };
  }, [refreshToken]);

  const reload = () => {
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
  };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings || !draft) return;
    setState("saving");
    setMessage("");
    void saveMaintenanceSettings(settings.revision, draft).then((next) => {
      setSettings(next);
      setDraft(next.values);
      onApplied(next.values);
      setState("saved");
      setMessage("Saved and applied to all connected clients.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to save settings");
    });
  };

  return (
    <PaneFrame
      className="maintenance-frame"
      header={<PaneHeader
        title="Maintenance"
        meta="Shared frontend runtime settings"
        actions={<button type="button" className="maintenance-secondary-button" onClick={reload} disabled={state === "loading" || state === "saving"}>Reload</button>}
      />}
    >
      <form className="maintenance-form" onSubmit={submit}>
        <div className="maintenance-intro">Changes are validated by the server, persisted for the next restart, and applied immediately to every connected client.</div>
        {settings?.sections.map((section) => (
          <section key={section.id} className="maintenance-section">
            <div className="maintenance-section-copy">
              <h2>{section.label}</h2>
              {section.description && <p>{section.description}</p>}
            </div>
            <div className="maintenance-table-wrap">
              <table className="maintenance-table">
                <thead><tr><th>Parameter</th><th>Value</th><th>Range</th><th>Apply</th></tr></thead>
                <tbody>
                  {section.settings.map((setting) => {
                    const value = draft?.[setting.key];
                    return (
                      <tr key={setting.key}>
                        <th scope="row"><span>{setting.label}</span>{setting.description && <small>{setting.description}</small>}</th>
                        <td>
                          {setting.type === "boolean" ? (
                            <button
                              type="button"
                              role="switch"
                              aria-checked={Boolean(value)}
                              className={`maintenance-switch ${value ? "is-on" : "is-off"}`}
                              disabled={!draft || state === "saving"}
                              onClick={() => setDraft((current) => current ? { ...current, [setting.key]: !current[setting.key] } : current)}
                            >
                              <span className="maintenance-switch-track" aria-hidden="true"><span className="maintenance-switch-thumb" /></span>
                              <span>{value ? "On" : "Off"}</span>
                            </button>
                          ) : setting.type === "select" ? (
                            <select value={String(value ?? "")} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)}>
                              {setting.options?.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                            </select>
                          ) : (
                            <input type="number" value={String(value ?? "")} min={setting.min} max={setting.max} step={setting.step ?? 1} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)} />
                          )}
                          {setting.unit && <span className="maintenance-unit">{setting.unit}</span>}
                        </td>
                        <td>{setting.type === "boolean" ? "—" : `${setting.min ?? "—"}–${setting.max ?? "—"}`}</td>
                        <td><span className={`maintenance-apply maintenance-apply-${setting.apply}`}>{setting.apply}</span></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </section>
        ))}
        <footer className="maintenance-actions">
          <span className={`maintenance-message maintenance-message-${state}`} role="status">{state === "loading" ? "Loading settings…" : message}</span>
          <button type="submit" className="maintenance-save-button" disabled={!draft || state === "loading" || state === "saving"}>{state === "saving" ? "Saving…" : "Save and apply"}</button>
        </footer>
      </form>
    </PaneFrame>
  );
}
.maintenance-frame {
  max-width: 1100px;
}

.maintenance-frame .pane-body {
  overflow: auto;
}

.maintenance-form {
  display: grid;
  gap: var(--space-4);
  padding: var(--space-3);
}

.maintenance-intro,
.maintenance-section {
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.maintenance-intro {
  padding: var(--space-3);
  color: var(--muted);
}

.maintenance-section-copy {
  padding: var(--space-3) var(--space-3) 0;
}

.maintenance-section-copy h2 {
  margin: 0;
  color: var(--text-strong);
  font-size: var(--font-size-md);
}

.maintenance-section-copy p {
  margin: var(--space-1) 0 0;
  color: var(--muted);
}

.maintenance-table-wrap {
  overflow-x: auto;
  padding: var(--space-3);
}

.maintenance-table {
  width: 100%;
  min-width: 660px;
  border-collapse: collapse;
}

.maintenance-table th,
.maintenance-table td {
  padding: var(--space-2);
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: middle;
}

.maintenance-table thead th {
  color: var(--muted);
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.maintenance-table tbody tr:last-child th,
.maintenance-table tbody tr:last-child td {
  border-bottom: 0;
}

.maintenance-table tbody th > span,
.maintenance-table tbody th > small {
  display: block;
}

.maintenance-table tbody th > span {
  color: var(--text-strong);
}

.maintenance-table tbody th > small {
  max-width: 460px;
  margin-top: 3px;
  color: var(--muted);
  font-size: var(--font-size-xs);
  font-weight: 400;
}

.maintenance-table input,
.maintenance-table select {
  width: 120px;
  min-height: var(--control-height);
  padding: 0 var(--space-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-muted);
  color: var(--text-strong);
}

.maintenance-unit {
  margin-left: var(--space-1);
  color: var(--muted);
}

.maintenance-apply {
  display: inline-flex;
  min-height: 22px;
  align-items: center;
  padding: 0 7px;
  border: 1px solid var(--success);
  border-radius: var(--radius-sm);
  background: var(--success-soft);
  color: var(--success);
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.maintenance-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}

.maintenance-message {
  color: var(--muted);
}

.maintenance-message-error {
  color: var(--danger);
}

.maintenance-message-saved {
  color: var(--success);
}

.maintenance-save-button,
.maintenance-secondary-button {
  min-height: var(--control-height);
  padding: 0 var(--space-3);
  border: 1px solid var(--accent-border);
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: var(--text-inverse);
  cursor: pointer;
  font-weight: 700;
}

.maintenance-secondary-button {
  background: var(--surface-muted);
  color: var(--text);
}

.maintenance-save-button:disabled,
.maintenance-secondary-button:disabled {
  cursor: wait;
  opacity: .6;
}

.maintenance-switch {
  display: inline-flex;
  min-width: 76px;
  min-height: var(--control-height);
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 9px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  background: var(--surface-muted);
  color: var(--muted);
  cursor: pointer;
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.maintenance-switch-track {
  display: inline-flex;
  width: 28px;
  height: 16px;
  align-items: center;
  padding: 2px;
  border-radius: 999px;
  background: var(--line-strong);
  transition: background-color .15s ease;
}

.maintenance-switch-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--surface);
  box-shadow: var(--shadow-sm);
  transition: transform .15s ease;
}

.maintenance-switch.is-on {
  border-color: var(--success);
  background: var(--success-soft);
  color: var(--success);
}

.maintenance-switch.is-on .maintenance-switch-track {
  background: var(--success);
}

.maintenance-switch.is-on .maintenance-switch-thumb {
  transform: translateX(12px);
}

.maintenance-switch:disabled {
  cursor: wait;
  opacity: .6;
}

