monitor::monitor()
	: monitor(config{}) {
}

monitor::monitor(config cfg)
	: m_cfg(std::move(cfg)),
	  m_reorder(m_cfg.reorder_holdback_sec) {
	m_init_status = init();
}

monitor::~monitor() {
}

int monitor::init() {
	{
		std::ios::sync_with_stdio(false);
		std::cin.tie(nullptr);
	}

	if(m_cfg.protocol_map_file.empty() == false) {
		if(m_protocol_map.load(m_cfg.protocol_map_file) != 0) {
			return -1;
		}
	}


	m_logs = std::make_unique<log_pipeline>(m_cfg.log);
	m_alerts = std::make_unique<alert_evaluator>(m_logs->events());
	if(!m_cfg.alert_config_file.empty() && m_alerts->load(m_cfg.alert_config_file) != 0) {
		return -1;
	}

	m_streams = std::make_unique<stream_registry>(m_protocol_map, m_logs->events());
	m_interfaces = std::make_unique<netif::interfaces>(netif::config{}, m_logs->events());

	m_pcap_source = pcap_input::make_source(m_cfg.input);
	if(!m_pcap_source) {
		trace(0, "error: failed to create pcap input source");
		return -1;
	}
	m_pcap_source->set_callback([this](const std::filesystem::path &path) {
		return process_pcap(path);
	});

	return 0;
}

int monitor::run() {
	if(m_init_status != 0) {
		return 1;
	}
	if(!m_pcap_source) {
		trace(0, "error: pcap input source is not initialized");
		return 1;
	}
	return m_pcap_source->run();
}

bool monitor::process_pcap(const std::filesystem::path& file_path) {
	std::string command = tshark::build_read_command(file_path, m_cfg.tshark, m_protocol_map.decode_as_rules());

	FILE* pipe = popen(command.c_str(), "r");
	if(!pipe) {
		return false;
	}

	const bool parse_ok = (process_tsv(pipe) == 0);
	if(!parse_ok) {
		trace(0, "warn: parse_tsv failed for %s", file_path.filename().string().c_str());
	}

	int status = pclose(pipe);
	if(status == -1) {
		trace(0, "warn: pclose failed for %s", file_path.filename().string().c_str());
		return false;
	}

	if(WIFEXITED(status)) {
		int exit_code = WEXITSTATUS(status);
		if(exit_code == 0) {
			return parse_ok;
		}

		trace(0, "warn: tshark failed for %s, exit_code=%d",
		      file_path.filename().string().c_str(),
		      exit_code);
		return false;
	}

	if(WIFSIGNALED(status)) {
		trace(0, "warn: tshark terminated by signal for %s, signal=%d",
		      file_path.filename().string().c_str(),
		      WTERMSIG(status));
		return false;
	}

	trace(0, "warn: tshark ended unexpectedly for %s, status=%d",
	      file_path.filename().string().c_str(),
	      status);

	return false;
}

