class stream_registry {
public:
	stream_registry(const protocol_map &protocols, event_sink &events);

	int process_packet(tsv::ctx &tc, const tsv::row_t &row, const packet_context &packet);
	void update_events(double now);
	void append_metrics(double now, json::array_t &out);
	void append_list(double now, json::array_t &out);

private:
	struct protocol_configs {
		hls::config hls;
		srt::config srt;
		rtp::config rtp;
		rtmp::config rtmp;
		other::config other;
	};

	const protocol_map &m_protocols;
	std::unique_ptr<srt::streams> m_srt;
	std::unique_ptr<rtp::streams> m_rtp;
	std::unique_ptr<rtmp::streams> m_rtmp;
	std::unique_ptr<hls::streams> m_hls;
	std::unique_ptr<other::streams> m_other;
	std::vector<::streams*> m_all_streams;
	std::vector<::streams*> m_output_streams;
	std::unordered_map<std::string_view, ::streams*> m_dispatcher;
	std::vector<std::unique_ptr<protocol_dispatch_adapter>> m_dispatch_adapters;

	static protocol_configs make_protocol_configs(const protocol_map &protocols);
	void register_stream(::streams &stream);
	::streams* dispatch_target(std::string_view proto) const;
};

