#include "stream_registry.h"

#include <utility>

#include "event.h"

stream_registry::protocol_configs stream_registry::make_protocol_configs(const protocol_map &protocols) {
	protocol_configs cfg{};
	cfg.rtp.fec_base_endpoints = protocols.rtp_fec_base_endpoints();
	return cfg;
}

stream_registry::stream_registry(const protocol_map &protocols, event_sink &events)
	: m_protocols(protocols) {
	auto cfg = make_protocol_configs(protocols);

	m_srt = std::make_unique<srt::streams>(cfg.srt, events);
	m_rtp = std::make_unique<rtp::streams>(cfg.rtp, events);
	m_rtmp = std::make_unique<rtmp::streams>(cfg.rtmp, events);
	m_hls = std::make_unique<hls::streams>(cfg.hls, events);
	m_other = std::make_unique<other::streams>(cfg.other, events);

	m_all_streams = { m_srt.get(), m_rtp.get(), m_rtmp.get(), m_hls.get(), m_other.get() };
	// Preserve the existing monitor output order. RTMP dispatch exists, but metrics/list output was not emitted before this refactor.
	m_output_streams = { m_srt.get(), m_rtp.get(), m_hls.get(), m_other.get() };

	dispatch_adapter_context dispatch_ctx{
		.protocols = m_protocols,
		.other_fallback = *m_other,
	};
	for(auto *stream : m_all_streams) {
		register_stream(*stream);
		if(auto adapter = stream->make_dispatch_adapter(dispatch_ctx)) {
			m_dispatch_adapters.emplace_back(std::move(adapter));
		}
	}
}

void stream_registry::register_stream(::streams &stream) {
	for(auto proto : stream.dispatch_protocols()) {
		m_dispatcher.emplace(proto, &stream);
	}
}

::streams* stream_registry::dispatch_target(std::string_view proto) const {
	const auto it = m_dispatcher.find(proto);
	if(it == m_dispatcher.end()) {
		return nullptr;
	}
	return it->second;
}

int stream_registry::process_packet(tsv::ctx &tc, const tsv::row_t &row, const packet_context &packet) {
	std::vector<protocol_dispatch_decision> dispatch_decisions;
	dispatch_decisions.reserve(m_dispatch_adapters.size());
	bool adapter_observe_stream = false;
	bool adapter_suppress_other = false;
	for(auto &adapter : m_dispatch_adapters) {
		auto decision = adapter->prepare(packet);
		adapter_observe_stream = adapter_observe_stream || decision.observe_stream;
		adapter_suppress_other = adapter_suppress_other || decision.suppress_other;
		dispatch_decisions.emplace_back(std::move(decision));
	}

	bool dispatched_to_stream = false;
	const bool observe_stream =
		m_protocols.should_observe(packet.dispatch_proto, packet.src, packet.dst, packet.vlan, packet.host) ||
		adapter_observe_stream;
	if(observe_stream) {
		if(auto *target = dispatch_target(packet.dispatch_proto)) {
			target->process(tc, row);
			dispatched_to_stream = true;
		}
		else if(!adapter_suppress_other) {
			m_other->process(tc, row);
		}
	}

	for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
		m_dispatch_adapters[i]->after_stream_dispatch(tc, row, packet, dispatch_decisions[i], dispatched_to_stream);
	}
	for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
		m_dispatch_adapters[i]->after_packet(tc, row, packet, dispatch_decisions[i]);
	}

	return 0;
}

void stream_registry::update_events(double now) {
	for(auto &adapter : m_dispatch_adapters) {
		adapter->prune(now);
	}
	for(auto *stream : m_output_streams) {
		stream->update_events(now);
	}
}

void stream_registry::append_metrics(double now, json::array_t &out) {
	for(auto *stream : m_output_streams) {
		stream->append_metrics(now, out);
	}
}

void stream_registry::append_list(double now, json::array_t &out) {
	for(auto *stream : m_output_streams) {
		stream->append_list(now, out);
	}
}
