class stream_registry {
public:
	stream_registry(const protocol_map &protocols, event_sink &events);

	int process_packet(tsv::ctx &tc, const tsv::row_t &row, const packet_context &packet);
	void update_events(double now);
	void append_metrics(double now, json::array_t &out);
	void append_list(double now, json::array_t &out);

