	struct protocol_configs {
		hls::config hls;
		srt::config srt;
		rtp::config rtp;
		rtmp::config rtmp;
		other::config other;
	};

	const protocol_map &m_protocols;
	std::unique_ptr<srt::streams> m_srt;
	std::unique_ptr<rtp::streams> m_rtp;
	std::unique_ptr<rtmp::streams> m_rtmp;
