	std::vector<::streams*> m_all_streams;
	std::vector<::streams*> m_output_streams;
	std::unordered_map<std::string_view, ::streams*> m_dispatcher;
	std::vector<std::unique_ptr<protocol_dispatch_adapter>> m_dispatch_adapters;

	static protocol_configs make_protocol_configs(const protocol_map &protocols);
	void register_stream(::streams &stream);
	::streams* dispatch_target(std::string_view proto) const;
};

