int flow::process(const info &i) {
	touch(i.time_epoch);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.jitter.update(i.time_epoch, i.timestamp);
	m_metrics.interval.update(i.time_epoch);
	m_metrics.packet_rate.update(i.time_epoch);
	m_metrics.packet_count.inc();

	auto ex = m_metrics.seq_ext.update(static_cast<std::uint16_t>(i.seq));
	if(ex.updated) {
		auto seq_update = m_metrics.seq_stats.update(ex.ext_seq);
		m_event.packet.loss_gap_count += seq_update.gap_added;
		if(seq_update.duplicate) {
			++m_event.packet.duplicate_count;
		}
		if(seq_update.reordered) {
			++m_event.packet.reorder_count;
		}
	}

	auto tx = m_metrics.ts_ext.update(i.timestamp);
	if(tx.updated) {
		m_metrics.skew.update(i.time_epoch, tx.ext_ts);
	}

	return 0;
}

