std::string lower(std::string_view value) {
	std::string out;
	out.reserve(value.size());
	for(unsigned char ch : value) {
		out.push_back(static_cast<char>(std::tolower(ch)));
	}
	return out;
}

std::string strip_query_fragment(std::string_view value) {
	const auto q = value.find('?');
	const auto f = value.find('#');
	std::size_t end = value.size();
	if(q != std::string_view::npos) end = std::min(end, q);
	if(f != std::string_view::npos) end = std::min(end, f);
	return std::string(value.substr(0, end));
}

std::string path_dir(std::string_view path) {
	const auto stripped = strip_query_fragment(path);
	const auto slash = stripped.rfind('/');
	if(slash == std::string::npos) {
		return {};
	}
	return stripped.substr(0, slash + 1);
}

bool path_ends_with(std::string_view path, std::string_view suffix) {
	const auto p = lower(strip_query_fragment(path));
	return p.size() >= suffix.size() && p.compare(p.size() - suffix.size(), suffix.size(), suffix) == 0;
}

std::string classify_role(std::string_view path) {
	if(path_ends_with(path, ".m3u8")) {
		return "playlist";
	}
	if(path_ends_with(path, ".ts") ||
	   path_ends_with(path, ".m4s") ||
	   path_ends_with(path, ".mp4") ||
	   path_ends_with(path, ".aac") ||
	   path_ends_with(path, ".vtt")) {
		return "segment";
	}
	if(path_ends_with(path, ".key")) {
		return "key";
	}
	return "other";
}

std::uint16_t endpoint_port(const ip_endpoint &ep, std::uint16_t fallback) {
	return ep.port != 0 ? ep.port : fallback;
}

std::string endpoint_key(const ip_endpoint &ep) {
	std::ostringstream oss;
	oss << to_string(ep.addr) << ':' << ep.port;
	return oss.str();
}

bool is_server_to_client_payload(const flow_id &fid, const info &i) {
	return i.has_tcp_payload && i.src.port == fid.port && i.dst.port != fid.port;
}

void split_host_port(std::string &host, std::uint16_t &port) {
	if(host.empty()) {
		return;
	}
	if(host.front() == '[') {
		const auto close = host.find(']');
		if(close == std::string::npos || close + 2 > host.size() || host[close + 1] != ':') {
			return;
		}
		std::uint32_t p = 0;
		if(tsv::to_number(std::string_view(host).substr(close + 2), p) && p <= 65535U) {
			port = static_cast<std::uint16_t>(p);
			host = host.substr(1, close - 1);
		}
		return;
	}

	const auto pos = host.rfind(':');
	if(pos == std::string::npos || host.find(':') != pos) {
		return;
	}
	std::uint32_t p = 0;
	if(tsv::to_number(std::string_view(host).substr(pos + 1), p) && p <= 65535U) {
		port = static_cast<std::uint16_t>(p);
		host = host.substr(0, pos);
	}
}

void parse_absolute_uri(std::string &host, std::uint16_t &port, std::string &path) {
	const auto scheme = path.find("://");
	if(scheme == std::string::npos) {
		return;
	}
	const auto auth_start = scheme + 3;
	const auto path_start = path.find('/', auth_start);
	std::string authority = path_start == std::string::npos ? path.substr(auth_start)
	                                                        : path.substr(auth_start, path_start - auth_start);
	if(host.empty()) {
		host = authority;
		split_host_port(host, port);
	}
	path = path_start == std::string::npos ? std::string{"/"} : path.substr(path_start);
}

std::string endpoint_text(std::string_view host, std::uint16_t port, std::string_view path) {
	std::ostringstream oss;
	oss << host;
	if(port != 0) {
		oss << ':' << port;
	}
	oss << path;
	return oss.str();
}

