		{"5xx", { {"window", s.s5xx.count()}, {"total", s.s5xx.total()} }},
		{"other", { {"window", s.other.count()}, {"total", s.other.total()} }},
	};
}

json stats_json(const metrics::value_stats &s) {
	return json{
		{"count", s.count},
		{"min", s.min},
		{"max", s.max},
		{"avg", s.avg()},
	};
