stream_id stream_id::from_playlist(std::uint32_t interface_id,
                                   std::string_view host,
                                   std::uint16_t port,
                                   std::string_view playlist_path,
                                   tsv::vlan_info vlan) {
	return stream_id{
		.interface_id = interface_id,
		.host = std::string(host),
		.port = port,
		.playlist_path = std::string(playlist_path),
		.vlan = std::move(vlan),
	};
}

std::string stream_id::to_stream_key() const {
	std::ostringstream oss;
	oss << proto_name << "|if=" << interface_id << tsv::key_suffix(vlan)
	    << "|playlist=" << endpoint_text(host, port, playlist_path);
	return oss.str();
}

std::size_t stream_id_hash::operator()(const stream_id& v) const noexcept {
	std::size_t h = 0;
	hash_combine(h, std::hash<std::uint32_t>{}(v.interface_id));
	hash_combine(h, std::hash<std::string>{}(v.host));
	hash_combine(h, std::hash<std::uint16_t>{}(v.port));
	hash_combine(h, std::hash<std::string>{}(v.playlist_path));
	hash_combine(h, tsv::hash_value(v.vlan));
	return h;
}

flow_id flow_id::from_request(std::uint32_t interface_id,
                              std::string_view host,
                              std::uint16_t port,
                              std::string_view path,
                              std::string_view role,
                              tsv::vlan_info vlan) {
	return flow_id{
		.interface_id = interface_id,
		.host = std::string(host),
		.port = port,
		.path = std::string(path),
		.role = std::string(role),
		.vlan = std::move(vlan),
	};
}

std::string flow_id::to_flow_key(const stream_id& sid) const {
	std::ostringstream oss;
	oss << sid.to_stream_key() << "|role=" << role;
	return oss.str();
}

bool flow_id::operator==(const flow_id& other) const {
	return interface_id == other.interface_id &&
	       host == other.host &&
	       port == other.port &&
	       role == other.role &&
	       vlan == other.vlan;
}

std::size_t flow_id_hash::operator()(const flow_id& v) const noexcept {
	std::size_t h = 0;
	hash_combine(h, std::hash<std::uint32_t>{}(v.interface_id));
	hash_combine(h, std::hash<std::string>{}(v.host));
	hash_combine(h, std::hash<std::uint16_t>{}(v.port));
	hash_combine(h, std::hash<std::string>{}(v.role));
	hash_combine(h, tsv::hash_value(v.vlan));
	return h;
}

void status_counters::update(std::uint16_t status) {
	total.inc();
	if(status >= 200 && status < 300) s2xx.inc();
	else if(status >= 300 && status < 400) s3xx.inc();
	else if(status >= 400 && status < 500) s4xx.inc();
	else if(status >= 500 && status < 600) s5xx.inc();
	else other.inc();
}

void status_counters::reset_window() {
	total.reset();
	s2xx.reset();
	s3xx.reset();
	s4xx.reset();
	s5xx.reset();
	other.reset();
}

