flow::flow(const stream_id& sid, const flow_id fid, std::string interface_name, event_sink &events)
	: m_fid(std::move(fid))
	, m_interface_name(std::move(interface_name))
	, m_events(events) {
	m_identity = flow_identity_cache{
		.stream_key = make_stream_key(sid),
		.flow_key = make_flow_key(sid, m_fid),
	};

	m_text = flow_text_cache{
		.role = to_string(m_fid.role),
		.src = to_string(m_fid.src),
		.dst = to_string(m_fid.dst),
	};

	m_event.source = stream_json::make_flow_event_source("RTP",
	                                                        m_fid.interface_id,
	                                                        m_interface_name,
	                                                        m_identity.stream_key,
	                                                        m_identity.flow_key,
	                                                        m_fid.vlan);
}

void flow::emit_detected(double now) {
	m_events.emit(make_event(now, "flow_detected", json{
		{"interface_id", m_fid.interface_id},
		{"role", m_text.role},
		{"endpoint", {
			{"src", m_text.src},
			{"dst", m_text.dst},
		}},
	}));
}

void flow::emit_lost(double now) {
	m_events.emit(make_event(now, "flow_lost", json{
		{"interface_id", m_fid.interface_id},
		{"role", m_text.role},
		{"endpoint", {
			{"src", m_text.src},
			{"dst", m_text.dst},
		}},
		{"last_seen", last_seen()},
	}));
}

int flow::process(const info &i) {
	touch(i.time_epoch);

	m_metrics.bitrate.update(i.time_epoch, i.frame_len);
	m_metrics.jitter.update(i.time_epoch, i.timestamp);
	m_metrics.interval.update(i.time_epoch);
	m_metrics.packet_rate.update(i.time_epoch);
	m_metrics.packet_count.inc();

	auto ex = m_metrics.seq_ext.update(static_cast<std::uint16_t>(i.seq));
	if(ex.updated) {
		auto seq_update = m_metrics.seq_stats.update(ex.ext_seq);
		m_event.packet.loss_gap_count += seq_update.gap_added;
		if(seq_update.duplicate) {
			++m_event.packet.duplicate_count;
		}
		if(seq_update.reordered) {
			++m_event.packet.reorder_count;
		}
	}

	auto tx = m_metrics.ts_ext.update(i.timestamp);
	if(tx.updated) {
		m_metrics.skew.update(i.time_epoch, tx.ext_ts);
	}

	return 0;
}

json flow::to_list_json(double now) const {
	(void)now;
	json j = stream_json::make_flow_list_base(m_identity.flow_key,
	                                               m_fid.interface_id,
	                                               m_interface_name,
	                                               m_fid.vlan);
	j["role"] = m_text.role;
	j["ssrc"] = m_fid.ssrc;
	j["payload_type"] = m_fid.payload_type;
	j["endpoint"] = {
		{"src", m_text.src},
		{"dst", m_text.dst},
	};
	j["last_seen"] = last_seen();
	return j;
}

int flow::append_metrics(double now, json::array_t &out) {
	flow_metrics &m = m_metrics;
	const auto bitrate = m.bitrate.snapshot_at(now);
	const auto packet_rate = m.packet_rate.snapshot_at(now);

	json j = stream_json::make_flow_metrics_base("RTP",
	                                               m_fid.interface_id,
	                                               m_interface_name,
	                                               m_identity.stream_key,
	                                               m_identity.flow_key,
	                                               m_fid.vlan);
	j["role"] = m_text.role;
	j["ssrc"] = m_fid.ssrc;
	j["payload_type"] = m_fid.payload_type;
	j["endpoint"] = {
		{"src", m_text.src},
		{"dst", m_text.dst},
	};
	j.update(json{
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"packet_rate", {
			{"pps", packet_rate.pps},
			{"count", packet_rate.stats.count},
			{"min", packet_rate.stats.min},
			{"max", packet_rate.stats.max},
			{"avg", packet_rate.stats.avg()},
		}},
		{"packet_count", {
			{"window", m.packet_count.count()},
			{"total", m.packet_count.total()},
		}},
		{"interval", {
			{"seconds", m.interval.value()},
			{"count", m.interval.stats().count},
			{"min", m.interval.stats().min},
			{"max", m.interval.stats().max},
			{"avg", m.interval.stats().avg()},
		}},
        {"jitter", {
	        {"seconds", m.jitter.value_sec()},
			{"count", m.jitter.stats_sec().count},
			{"min", m.jitter.stats_sec().min},
			{"max", m.jitter.stats_sec().max},
			{"avg", m.jitter.stats_sec().avg()},
        }},
        {"clock_skew", {
	        {"skew_ppm", m.skew.skew_ppm()},
	        {"skew_ratio", m.skew.skew_ratio()},
	        {"observed_rate", m.skew.observed_rate()},
        }},
        {"seq_stats", {
	        {"gap", {
		        {"window", m.seq_stats.gap_count().count()},
		        {"total", m.seq_stats.gap_count().total()},
	        }},
	        {"dup", {
		        {"window", m.seq_stats.dup_count().count()},
		        {"total", m.seq_stats.dup_count().total()},
	        }},
	        {"reorder", {
		        {"window", m.seq_stats.reorder_count().count()},
		        {"total", m.seq_stats.reorder_count().total()},
	        }},
        }}
	});

	m.bitrate.clear_stats();
	m.packet_rate.clear_stats();
	m.packet_count.reset();
	m.interval.clear_stats();
	m.seq_stats.reset_stats();

	out.push_back(std::move(j));
	m_metrics_emitted = true;

	return 0;
}

