std::size_t stream_id_hash::operator()(const stream_id& v) const noexcept {
	std::size_t h = 0;
	hash_combine(h, std::hash<std::uint32_t>{}(v.interface_id));
	hash_combine(h, std::hash<std::string>{}(v.host));
	hash_combine(h, std::hash<std::uint16_t>{}(v.port));
	hash_combine(h, std::hash<std::string>{}(v.playlist_path));
	hash_combine(h, tsv::hash_value(v.vlan));
