	hash_combine(h, std::hash<std::string>{}(v.role));
	hash_combine(h, tsv::hash_value(v.vlan));
	return h;
}

void status_counters::update(std::uint16_t status) {
	total.inc();
	if(status >= 200 && status < 300) s2xx.inc();
	else if(status >= 300 && status < 400) s3xx.inc();
	else if(status >= 400 && status < 500) s4xx.inc();
	else if(status >= 500 && status < 600) s5xx.inc();
	else other.inc();
}

void status_counters::reset_window() {
	total.reset();
	s2xx.reset();
	s3xx.reset();
	s4xx.reset();
	s5xx.reset();
	other.reset();
}

