export async function getAppConfig(): Promise<AppConfig> {
  return getJson("/api/config");
}

export async function getMaintenanceSettings(): Promise<MaintenanceSettingsResponse> {
  return getJson("/api/maintenance/frontend-settings");
}

export async function saveMaintenanceSettings(revision: number, values: AppConfig): Promise<MaintenanceSettingsResponse> {
  const response = await fetch("/api/maintenance/frontend-settings", {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ revision, values })
  });
  if (!response.ok) {
    const body = await response.json().catch(() => undefined) as { error?: string } | undefined;
    throw new Error(body?.error ?? "Request failed");
  }
  return response.json() as Promise<MaintenanceSettingsResponse>;
}

export async function getBootstrap(): Promise<BootstrapResponse> {
  return getJson("/api/bootstrap");
}

export async function getTopology(timeSec?: number): Promise<TopologySnapshot> {
  const suffix = timeSec !== undefined ? `?time=${encodeURIComponent(String(timeSec))}` : "";
  return getJson(`/api/topology${suffix}`);
}

export async function getTimeline(query: TimelineRangeQuery = {}): Promise<TimelineViewResponse> {
  const params = new URLSearchParams();
  if (query.from !== undefined) params.set("from", String(query.from));
  if (query.to !== undefined) params.set("to", String(query.to));
  if (query.includeFlows !== undefined) params.set("includeFlows", query.includeFlows ? "1" : "0");
  const suffix = params.toString() ? `?${params.toString()}` : "";
  return getJson(`/api/timeline${suffix}`);
}

export async function getInterfaces(): Promise<InterfaceListItem[]> {
  return getJson("/api/interfaces");
}

export async function getInterfaceMetrics(interfaceId: number, windowSec = 300): Promise<InterfaceMetricsResponse> {
  return getJson(`/api/interfaces/${interfaceId}/metrics?windowSec=${windowSec}`);
}

export async function getInterfaceMetricsByKey(key: string, query: number | MetricsRangeQuery = 300): Promise<InterfaceMetricsResponse> {
  const params = new URLSearchParams();
  if (typeof query === "number") params.set("windowSec", String(query));
  else {
    if (query.windowSec !== undefined) params.set("windowSec", String(query.windowSec));
    if (query.from !== undefined) params.set("from", String(query.from));
    if (query.to !== undefined) params.set("to", String(query.to));
  }
  return getJson(`/api/interfaces/by-key/${encodeURIComponent(key)}/metrics?${params.toString()}`);
}

export async function getSummary(): Promise<Summary> {
  return getJson("/api/summary");
}

export async function getStream(streamKey: string): Promise<StreamState> {
  return getJson(`/api/streams/${encodeURIComponent(streamKey)}`);
}

export async function getStreamMetrics(streamKey: string, query: number | MetricsRangeQuery = 300): Promise<StreamMetricsResponse> {
  const params = new URLSearchParams();
  if (typeof query === "number") {
    params.set("windowSec", String(query));
  } else {
    if (query.windowSec !== undefined) params.set("windowSec", String(query.windowSec));
    if (query.from !== undefined) params.set("from", String(query.from));
    if (query.to !== undefined) params.set("to", String(query.to));
    if (query.resolutionSec !== undefined) params.set("resolutionSec", String(query.resolutionSec));
  }
  return getJson(`/api/streams/${encodeURIComponent(streamKey)}/metrics?${params.toString()}`);
}

export async function getEvents(params: {
  streamKey?: string;
  flowKey?: string;
  interfaceId?: number;
  limit?: number;
  from?: number;
  to?: number;
  proto?: string;
  level?: "info" | "warn" | "error";
  type?: string;
} = {}): Promise<EventLogItem[]> {
  const query = new URLSearchParams();
  if (params.streamKey) query.set("streamKey", params.streamKey);
  if (params.flowKey) query.set("flowKey", params.flowKey);
  if (params.interfaceId !== undefined) query.set("interfaceId", String(params.interfaceId));
  if (params.from !== undefined) query.set("from", String(params.from));
  if (params.to !== undefined) query.set("to", String(params.to));
  if (params.proto) query.set("proto", params.proto);
  if (params.level) query.set("level", params.level);
  if (params.type) query.set("type", params.type);
  if (params.limit) query.set("limit", String(params.limit));
  const suffix = query.toString() ? `?${query.toString()}` : "";
  return getJson(`/api/events${suffix}`);
}

async function getJson<T>(url: string): Promise<T> {
  const response = await fetch(url, { cache: "no-store" });
  if (!response.ok) throw new Error(`${response.status} ${response.statusText}`);
  return response.json() as Promise<T>;
}
