	j["ssrc"] = m_fid.ssrc;
	j["payload_type"] = m_fid.payload_type;
	j["endpoint"] = {
		{"src", m_text.src},
		{"dst", m_text.dst},
	};
	j.update(json{
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"packet_rate", {
			{"pps", packet_rate.pps},
			{"count", packet_rate.stats.count},
			{"min", packet_rate.stats.min},
			{"max", packet_rate.stats.max},
			{"avg", packet_rate.stats.avg()},
		}},
		{"packet_count", {
			{"window", m.packet_count.count()},
			{"total", m.packet_count.total()},
		}},
		{"interval", {
			{"seconds", m.interval.value()},
			{"count", m.interval.stats().count},
			{"min", m.interval.stats().min},
			{"max", m.interval.stats().max},
			{"avg", m.interval.stats().avg()},
		}},
        {"jitter", {
	        {"seconds", m.jitter.value_sec()},
			{"count", m.jitter.stats_sec().count},
			{"min", m.jitter.stats_sec().min},
			{"max", m.jitter.stats_sec().max},
			{"avg", m.jitter.stats_sec().avg()},
        }},
        {"clock_skew", {
	        {"skew_ppm", m.skew.skew_ppm()},
	        {"skew_ratio", m.skew.skew_ratio()},
	        {"observed_rate", m.skew.observed_rate()},
        }},
        {"seq_stats", {
	        {"gap", {
		        {"window", m.seq_stats.gap_count().count()},
		        {"total", m.seq_stats.gap_count().total()},
	        }},
	        {"dup", {
		        {"window", m.seq_stats.dup_count().count()},
		        {"total", m.seq_stats.dup_count().total()},
	        }},
	        {"reorder", {
		        {"window", m.seq_stats.reorder_count().count()},
		        {"total", m.seq_stats.reorder_count().total()},
	        }},
        }}
	});

	m.bitrate.clear_stats();
	m.packet_rate.clear_stats();
	m.packet_count.reset();
	m.interval.clear_stats();
	m.seq_stats.reset_stats();

	out.push_back(std::move(j));
	m_metrics_emitted = true;

	return 0;
}

