protocol_map::observe_mode protocol_map::read_observe_mode(const json &j) {
	if(!j.is_object() || !j.contains("observe_mode") || j["observe_mode"].is_null()) {
		return observe_mode::all;
	}
	if(!j["observe_mode"].is_string()) {
		std::cerr << "protocol_map: observe_mode must be a string" << std::endl;
		return observe_mode::all;
	}

	const std::string mode = upper(j["observe_mode"].get<std::string>());
	if(mode == "ALL") {
		return observe_mode::all;
	}
	if(mode == "CONFIGURED_ONLY") {
		return observe_mode::configured_only;
	}
	if(mode == "CONFIGURED_PLUS_OTHER") {
		return observe_mode::configured_plus_other;
	}

	std::cerr << "protocol_map: unknown observe_mode " << j["observe_mode"].get<std::string>()
	          << ", fallback to all" << std::endl;
	return observe_mode::all;
}

bool protocol_map::auto_decode_as(std::string_view proto, unsigned port, std::string &out) {
	const std::string p = upper(proto);
	if(p == "SRT") {
		out = "udp.port==" + std::to_string(port) + ",srt";
		return true;
	}
	if(p == "RTP") {
		out = "udp.port==" + std::to_string(port) + ",rtp";
		return true;
	}
	if(p == "RTMP") {
		out = "tcp.port==" + std::to_string(port) + ",rtmpt";
		return true;
	}
	if(p == "HTTP" || p == "HLS") {
		out = "tcp.port==" + std::to_string(port) + ",http";
		return true;
	}
	return false;
}

void protocol_map::add_decode_as(std::string value) {
	if(value.empty()) {
		return;
	}
	if(std::find(m_decode_as_rules.begin(), m_decode_as_rules.end(), value) != m_decode_as_rules.end()) {
		return;
	}
	m_decode_as_rules.push_back(std::move(value));
}


bool protocol_map::proto_matches(std::string_view rule_proto, std::string_view observed_proto) {
	const std::string rule = upper(rule_proto);
	const std::string observed = upper(observed_proto);
	if(rule == observed) {
		return true;
	}
	return (rule == "HLS" && observed == "HTTP") ||
	       (rule == "HTTP" && observed == "HLS") ||
	       ((rule == "HLS" || rule == "HTTP") && is_tls_proto(observed_proto)) ||
	       (rule == "RTMP" && observed == "RTMPT") ||
	       (rule == "RTMPT" && observed == "RTMP");
}

bool protocol_map::is_dedicated_proto(std::string_view proto) {
	const std::string p = upper(proto);
	return p == "RTP" || p == "SRT" || p == "HTTP" || p == "HLS" || p == "RTMP" || p == "RTMPT";
}

bool protocol_map::vlan_matches(const vlan_match &rule_vlan, const tsv::vlan_info &packet_vlan) {
	switch(rule_vlan.type) {
	case vlan_match::mode::any:
		return true;
	case vlan_match::mode::untagged:
		return packet_vlan.empty();
	case vlan_match::mode::id:
		return packet_vlan.id == rule_vlan.id;
	}
	return false;
}

bool protocol_map::endpoint_matches(const rule &r, const ip_endpoint &configured, const ip_endpoint &candidate) {
	if(configured.addr == candidate.addr && configured.port == candidate.port) {
		return true;
	}

	if(!(upper(r.proto) == "RTP" && r.fec)) {
		return false;
	}
	if(!(configured.addr == candidate.addr)) {
		return false;
	}
	if(candidate.port < configured.port) {
		return false;
	}

	const auto offset = static_cast<unsigned>(candidate.port - configured.port);
	return offset == 2U || offset == 4U;
}

bool protocol_map::endpoint_matches(const rule &r, const ip_endpoint &candidate) {
	for(const auto &endpoint : r.endpoints) {
		ip_endpoint configured{};
		if(!parse_endpoint(endpoint, configured)) {
			continue;
		}
		if(endpoint_matches(r, configured, candidate)) {
			return true;
		}
	}
	return false;
}

bool protocol_map::host_matches(const rule &r, std::string_view host) {
	if(host.empty()) {
		return false;
	}

	const auto observed = lower_host(host);
	if(observed.empty()) {
		return false;
	}

	for(const auto &configured_host : r.hosts) {
		const auto configured = lower_host(configured_host);
		if(configured.empty()) {
			continue;
		}
		if(configured == observed) {
			return true;
		}
		if(configured.size() > 2 && configured[0] == '*' && configured[1] == '.') {
			const auto suffix = configured.substr(1);
			if(observed.size() >= suffix.size() &&
			   observed.compare(observed.size() - suffix.size(), suffix.size(), suffix) == 0) {
				return true;
			}
		}
	}

	return false;
}

bool protocol_map::should_observe(std::string_view proto,
                                  const ip_endpoint &src,
                                  const ip_endpoint &dst,
                                  const tsv::vlan_info &vlan,
                                  std::string_view host) const {
	if(m_observe_mode == observe_mode::all) {
		return true;
	}
	if(m_observe_mode == observe_mode::configured_plus_other && !is_dedicated_proto(proto)) {
		return true;
	}

	for(const auto &r : m_rules) {
		if(!r.observe) {
			continue;
		}
		if(!proto_matches(r.proto, proto)) {
			continue;
		}
		if(!vlan_matches(r.vlan, vlan)) {
			continue;
		}
		if(endpoint_matches(r, src) || endpoint_matches(r, dst) || host_matches(r, host)) {
			return true;
		}
	}

	return false;
}


bool protocol_map::has_observable_host_rule(std::string_view proto, const tsv::vlan_info &vlan) const {
	for(const auto &r : m_rules) {
		if(!r.observe || r.hosts.empty()) {
			continue;
		}
		if(!proto_matches(r.proto, proto)) {
			continue;
		return nullptr;
	}
	return it->second;
}

int stream_registry::process_packet(tsv::ctx &tc, const tsv::row_t &row, const packet_context &packet) {
	std::vector<protocol_dispatch_decision> dispatch_decisions;
	dispatch_decisions.reserve(m_dispatch_adapters.size());
	bool adapter_observe_stream = false;
	bool adapter_suppress_other = false;
	for(auto &adapter : m_dispatch_adapters) {
		auto decision = adapter->prepare(packet);
		adapter_observe_stream = adapter_observe_stream || decision.observe_stream;
		adapter_suppress_other = adapter_suppress_other || decision.suppress_other;
		dispatch_decisions.emplace_back(std::move(decision));
	}

	bool dispatched_to_stream = false;
	const bool observe_stream =
		m_protocols.should_observe(packet.dispatch_proto, packet.src, packet.dst, packet.vlan, packet.host) ||
		adapter_observe_stream;
	if(observe_stream) {
		if(auto *target = dispatch_target(packet.dispatch_proto)) {
			target->process(tc, row);
			dispatched_to_stream = true;
		}
		else if(!adapter_suppress_other) {
			m_other->process(tc, row);
		}
	}

	for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
		m_dispatch_adapters[i]->after_stream_dispatch(tc, row, packet, dispatch_decisions[i], dispatched_to_stream);
	}
	for(std::size_t i = 0; i < m_dispatch_adapters.size(); ++i) {
		m_dispatch_adapters[i]->after_packet(tc, row, packet, dispatch_decisions[i]);
	}

	return 0;
}

void stream_registry::update_events(double now) {
	for(auto &adapter : m_dispatch_adapters) {
		adapter->prune(now);
	}
	for(auto *stream : m_output_streams) {
		stream->update_events(now);
	}
}

void stream_registry::append_metrics(double now, json::array_t &out) {
	for(auto *stream : m_output_streams) {
		stream->append_metrics(now, out);
	}
}

void stream_registry::append_list(double now, json::array_t &out) {
	for(auto *stream : m_output_streams) {
		stream->append_list(now, out);
	}
}
#include "hls_dispatch_adapter.h"

#include "trace.h"

namespace {

constexpr const char *hls_tcp_fallback_proto = "HLS-TCP";

} // namespace

hls_dispatch_adapter::hls_dispatch_adapter(const protocol_map &protocols,
                                           hls::streams &hls_streams,
                                           other::streams &other_streams)
	: m_protocols(protocols),
	  m_hls(hls_streams),
	  m_other(other_streams) {
}

protocol_dispatch_decision hls_dispatch_adapter::prepare(const packet_context &packet) {
	protocol_dispatch_decision out{};
	out.tracking_key = packet_connection_key(packet);
	out.matched =
		!packet.host.empty() &&
		m_protocols.should_observe("HTTP", packet.src, packet.dst, packet.vlan, packet.host);
	if(out.matched) {
		m_state.remember_candidate(out.tracking_key, packet.time_epoch);
	}

	out.tracked = m_state.known(out.tracking_key);
	out.observe_stream = packet.dispatch_proto == "HTTP" && out.tracked;
	out.suppress_other = out.matched || out.tracked;
	return out;
}

void hls_dispatch_adapter::after_stream_dispatch(tsv::ctx &,
                                                 const tsv::row_t &,
                                                 const packet_context &packet,
                                                 const protocol_dispatch_decision &decision,
                                                 bool dispatched_to_stream) {
	if(!dispatched_to_stream || packet.dispatch_proto != "HTTP") {
		return;
	}
	if(!decision.matched && !decision.tracked) {
		return;
	}
	m_state.remember_detailed(decision.tracking_key, packet.time_epoch);
}

void hls_dispatch_adapter::after_packet(tsv::ctx &tc,
                                        const tsv::row_t &row,
                                        const packet_context &packet,
                                        const protocol_dispatch_decision &decision) {
	if(packet.dispatch_proto == "HTTP" || !packet.has_tcp_payload || !decision.tracked) {
		return;
	}

	trace(4, "monitor: tcp payload fallback to HLS proto=%s tcp_len=%u src_port=%u dst_port=%u",
	      packet.proto.c_str(),
	      packet.tcp_len,
	      static_cast<unsigned>(packet.src.port),
	      static_cast<unsigned>(packet.dst.port));
	m_hls.process(tc, row);
	if(m_state.tcp_fallback_ready(decision.tracking_key, packet.time_epoch)) {
		m_other.process_as(tc, row, hls_tcp_fallback_proto);
	}
}

void hls_dispatch_adapter::prune(double now) {
	m_state.prune(now);
}
