struct stream_id_hash {
    std::size_t operator()(const stream_id& v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<std::uint32_t>{}(v.interface_id));
        hash_combine(h, std::hash<std::string>{}(v.proto));
        hash_combine(h, std::hash<std::uint8_t>{}(v.ip_proto));
        hash_combine(h, ip_endpoint_hash{}(v.endpoint));
        hash_combine(h, tsv::hash_value(v.vlan));
        return h;
    }
};

struct flow_id {
