struct stream_id {
    std::uint32_t interface_id{0};
    std::string proto;
    std::uint8_t ip_proto{0};
    ip_endpoint endpoint;
    tsv::vlan_info vlan;

    static bool is_ipv4_broadcast(const ip_addr& ip) {
        return !ip.is_v6 &&
            ip.bytes[0] == 255 &&
            ip.bytes[1] == 255 &&
            ip.bytes[2] == 255 &&
            ip.bytes[3] == 255;
    }

    static bool is_multicast(const ip_addr& ip) {
        if (ip.is_v6) {
            return ip.bytes[0] == 0xff;
        }

        return ip.bytes[0] >= 224 && ip.bytes[0] <= 239;
    }

    static ip_endpoint select_service_endpoint(const ip_addr& src_ip, std::uint16_t src_port,
                                               const ip_addr& dst_ip, std::uint16_t dst_port) {
        ip_endpoint src{src_ip, src_port};
        ip_endpoint dst{dst_ip, dst_port};

        if (is_ipv4_broadcast(dst_ip) || is_multicast(dst_ip)) {
            return dst;
        }

        if (src.port != dst.port) {
            return (src.port < dst.port) ? src : dst;
        }

        return dst;
    }

    static stream_id from_packet(std::uint32_t interface_id,
                                 std::string_view proto_sv,
                                 std::uint8_t ip_proto,
                                 const ip_addr& src_ip, std::uint16_t src_port,
                                 const ip_addr& dst_ip, std::uint16_t dst_port,
                                 tsv::vlan_info vlan = {}) {
        return stream_id{
            .interface_id = interface_id,
            .proto = std::string(proto_sv),
            .ip_proto = ip_proto,
            .endpoint = select_service_endpoint(src_ip, src_port, dst_ip, dst_port),
            .vlan = std::move(vlan)
        };
    }

    std::string to_stream_key() const {
        return proto + "|if=" + std::to_string(interface_id) +
            tsv::key_suffix(vlan) +
            "|ep=" + to_string(endpoint);
    }

    bool operator==(const stream_id&) const = default;
};

struct stream_id_hash {
    std::size_t operator()(const stream_id& v) const noexcept {
        std::size_t h = 0;
        hash_combine(h, std::hash<std::uint32_t>{}(v.interface_id));
