	                                               m_interface_name,
	                                               m_fid.vlan);
	j["role"] = "flow";
	j["endpoint"] = {
		{"src", m_src_text},
		{"dst", m_dst_text},
	};
	out.push_back(std::move(j));
	return 0;
}

