/* -*- coding: utf-8 -*- */

#include "app.h"

#include <unistd.h>

#include <cstdint>
#include <cstdio>
#include <functional>
#include <string>

#include "app_config.h"
#include "cmdline.h"
#include "json.h"
#include "pcap_watch.h"
#include "task.h"
#include "trace.h"
#include "util.h"

static const char VERSION_STR[] = "0.0";



//--------------------------------------------------------------------------------
app::app() {
	m_abort = false;
}

//--------------------------------------------------------------------------------
app::~app() {
}

//--------------------------------------------------------------------------------
int app::run(int argc, char *argv[]) {
	if(parse_options(argc, argv, &m_param) != 0) {
		return -1;
	}

    task reporter(std::bind(&app::report, this), 1000);
    reporter.start();

    m_monitor = std::make_unique<monitor>(monitor::config{
		    .log = {
			    .dir = m_param.log_dir,
			    .event_journal_dir = m_param.event_journal_dir,
			    .metrics_journal_dir = m_param.metrics_journal_dir,
			    .journal_part_size_bytes = m_param.journal_part_size_bytes,
			    .journal_retention_hours = m_param.journal_retention_hours,
		    },
		    .input = {
			    .input_mode = m_param.input_mode,
			    .watch_dir = m_param.input_watch_dir,
			    .file = m_param.input_file,
			    .dir = m_param.input_dir,
			    .pcap_prefix = m_param.pcap_prefix,
			    .ring_file_count = m_param.pcap_ring_files,
			    .backlog_trend_threshold = m_param.pcap_backlog_trend_threshold,
		    },
		    .tshark = m_param.tshark,
		    .protocol_map_file = m_param.protocol_map_file,
		    .alert_config_file = m_param.alert_config_file,
	    });

	int rc = 0;
	if(!m_abort) {
		rc = m_monitor->run();
	}

    reporter.stop();

	return rc;
}

//--------------------------------------------------------------------------------
int app::stop() {
	m_abort = true;

	return 0;
}

//--------------------------------------------------------------------------------
std::string app::status() {
	std::string s;

	return s;
}

//--------------------------------------------------------------------------------
void app::report() {
//	std::cerr << "+" << std::endl;
}

//--------------------------------------------------------------------------------
int app::parse_options(int argc, char *argv[], app_param *p) {
	cmdline::parser cp;

	cp.add<std::string>("config", 'c', "unified stm config json file", false, "");
	cp.add<int>("debug", 'd', "debug log level", false, 1);
	cp.add<std::string>("name", 'n', "identity name", false, "");
	cp.add<std::string>("log-dir", 0, "journal output directory", false, "");
	cp.add<std::string>("log-event-journal-dir", 0, "event journal output directory", false, "event-journal");
	cp.add<std::string>("log-metrics-journal-dir", 0, "metrics journal output directory", false, "metrics-journal");
	cp.add<std::uint64_t>("log-journal-part-size-bytes", 0, "journal part max size bytes", false, 64ULL * 1024ULL * 1024ULL);
	cp.add<std::uint32_t>("log-journal-retention-hours", 0, "journal retention hours", false, 72U);
	cp.add<std::string>("input-watch-dir", 0, "watch directory for dumpcap ring pcaps", false, "/tmp/stm/capture/");
	cp.add<std::string>("input-file", 0, "single pcap/pcapng file to process and exit", false, "");
	cp.add<std::string>("input-dir", 0, "directory of pcap/pcapng files to process and exit", false, "");
	cp.add<std::string>("pcap-prefix", 0, "pcap filename prefix for watch mode", false, "cap_");
	cp.add<std::size_t>("pcap-ring-files", 0, "dumpcap ring file count for processed cache", false, 10);
	cp.add<std::size_t>("pcap-backlog-trend-threshold", 0, "backlog trend consecutive count threshold", false, 1);
	cp.add<std::string>("tshark-config", 0, "tshark command config json file", false, "");
	cp.add<std::string>("tshark-program", 0, "tshark program path", false, "tshark");
	cp.add<std::string>("tshark-fields", 0, "comma-separated tshark output fields replacing defaults", false, "");
	cp.add<std::string>("tshark-extra-fields", 0, "comma-separated additional tshark output fields", false, "");
	cp.add<std::string>("tshark-extra-args", 0, "comma-separated additional tshark args", false, "");
	cp.add<std::string>("alert-config", 0, "alert rule config json file", false, "");
	cp.add<std::string>("protocol-map", 0, "protocol map json file for tshark decode-as", false, "");
	cp.add("version", 'v', "show version");

	cp.parse_check(argc, argv);

	if(cp.exist("version")) {
		version(argv, VERSION_STR);
		return -1;
	}

	*p = app_param{};
	p->config_file = cp.get<std::string>("config");
	p->debug_level = cp.get<int>("debug");
	p->id_name.clear();
	p->log_dir = cp.get<std::string>("log-dir");
	p->event_journal_dir = cp.get<std::string>("log-event-journal-dir");
	p->metrics_journal_dir = cp.get<std::string>("log-metrics-journal-dir");
	p->journal_part_size_bytes = cp.get<std::uint64_t>("log-journal-part-size-bytes");
	p->journal_retention_hours = cp.get<std::uint32_t>("log-journal-retention-hours");
	p->input_watch_dir = cp.get<std::string>("input-watch-dir");
	p->input_file = cp.get<std::string>("input-file");
	p->input_dir = cp.get<std::string>("input-dir");
	p->pcap_prefix = cp.get<std::string>("pcap-prefix");
	p->pcap_ring_files = cp.get<std::size_t>("pcap-ring-files");
	p->pcap_backlog_trend_threshold = cp.get<std::size_t>("pcap-backlog-trend-threshold");
	p->tshark = tshark::read_config{};

	if(!p->config_file.empty() && apply_unified_config_file(p->config_file, p) != 0) {
		return -1;
	}

	if(cp.exist("name")) p->id_name = cp.get<std::string>("name");
	if(cp.exist("debug")) p->debug_level = cp.get<int>("debug");
	if(cp.exist("log-dir")) p->log_dir = cp.get<std::string>("log-dir");
	if(cp.exist("log-event-journal-dir")) p->event_journal_dir = cp.get<std::string>("log-event-journal-dir");
	if(cp.exist("log-metrics-journal-dir")) p->metrics_journal_dir = cp.get<std::string>("log-metrics-journal-dir");
	if(cp.exist("log-journal-part-size-bytes")) p->journal_part_size_bytes = cp.get<std::uint64_t>("log-journal-part-size-bytes");
	if(cp.exist("log-journal-retention-hours")) p->journal_retention_hours = cp.get<std::uint32_t>("log-journal-retention-hours");
	if(cp.exist("input-watch-dir")) p->input_watch_dir = cp.get<std::string>("input-watch-dir");
	if(cp.exist("input-file")) p->input_file = cp.get<std::string>("input-file");
	if(cp.exist("input-dir")) p->input_dir = cp.get<std::string>("input-dir");
	if(cp.exist("pcap-prefix")) p->pcap_prefix = cp.get<std::string>("pcap-prefix");
	if(cp.exist("pcap-ring-files")) p->pcap_ring_files = cp.get<std::size_t>("pcap-ring-files");
	if(cp.exist("pcap-backlog-trend-threshold")) p->pcap_backlog_trend_threshold = cp.get<std::size_t>("pcap-backlog-trend-threshold");

	if(cp.exist("tshark-config")) {
		p->tshark_config_file = cp.get<std::string>("tshark-config");
		p->tshark = tshark::read_config{};
		if(!p->tshark_config_file.empty() && tshark::load_config_file(p->tshark_config_file, p->tshark) != 0) {
			return -1;
		}
	}
	if(cp.exist("tshark-program")) p->tshark.program = cp.get<std::string>("tshark-program");
	if(!cp.get<std::string>("tshark-fields").empty()) p->tshark.fields = tshark::split_csv(cp.get<std::string>("tshark-fields"));
	if(!cp.get<std::string>("tshark-extra-fields").empty()) p->tshark.extra_fields = tshark::split_csv(cp.get<std::string>("tshark-extra-fields"));
	if(!cp.get<std::string>("tshark-extra-args").empty()) p->tshark.extra_args = tshark::split_csv(cp.get<std::string>("tshark-extra-args"));
	if(cp.exist("alert-config")) p->alert_config_file = cp.get<std::string>("alert-config");
	if(cp.exist("protocol-map")) p->protocol_map_file = cp.get<std::string>("protocol-map");

	if(p->id_name.empty()) {
		p->id_name = std::to_string(getpid());
	}

	if(!p->input_file.empty() && !p->input_dir.empty()) {
		std::fprintf(stderr, "--input-file and --input-dir are mutually exclusive\n");
		return -1;
	}
	if(!p->input_file.empty()) {
		p->input_mode = pcap_input::mode::file;
	}
	else if(!p->input_dir.empty()) {
		p->input_mode = pcap_input::mode::dir;
	}
	else {
		p->input_mode = pcap_input::mode::watch_dir;
	}

	set_trace_id(p->id_name.c_str());
	set_trace_level(p->debug_level);

	trace(1, "config: %s", p->config_file.c_str());
	trace(1, "id_name: %s", p->id_name.c_str());
	trace(1, "debug_level: %d", p->debug_level);
	trace(1, "log_dir: %s", p->log_dir.c_str());
	trace(1, "event_journal_dir: %s", p->event_journal_dir.c_str());
	trace(1, "metrics_journal_dir: %s", p->metrics_journal_dir.c_str());
	trace(1, "journal_part_size_bytes: %llu", static_cast<unsigned long long>(p->journal_part_size_bytes));
	trace(1, "journal_retention_hours: %u", static_cast<unsigned>(p->journal_retention_hours));
	trace(1, "input_watch_dir: %s", p->input_watch_dir.c_str());
	trace(1, "input_file: %s", p->input_file.c_str());
	trace(1, "input_dir: %s", p->input_dir.c_str());
	trace(1, "pcap_prefix: %s", p->pcap_prefix.c_str());
	trace(1, "pcap_ring_files: %zu", p->pcap_ring_files);
	trace(1, "pcap_backlog_trend_threshold: %zu", p->pcap_backlog_trend_threshold);
	trace(1, "tshark_config: %s", p->tshark_config_file.c_str());
	trace(1, "tshark_program: %s", p->tshark.program.c_str());
	trace(1, "tshark_fields: %zu", p->tshark.fields.size());
	trace(1, "tshark_extra_fields: %zu", p->tshark.extra_fields.size());
	trace(1, "tshark_extra_args: %zu", p->tshark.extra_args.size());
	trace(1, "alert_config: %s", p->alert_config_file.c_str());
	trace(1, "protocol_map: %s", p->protocol_map_file.c_str());

	return 0;
}

//--------------------------------------------------------------------------------
void app::version(char *argv[], const char *ver) {
	std::fprintf(stderr, "%s\n", ver);
}
