function resolveDirValue(value: unknown, label: string) {
  const dirName = String(value ?? "").trim();
  if (!dirName) throw new Error(`missing ${label} directory`);
  return dirName;
}
function resolveDirPath(baseDir: string, dirValue: string) { return path.isAbsolute(dirValue) ? dirValue : path.resolve(baseDir, dirValue); }
function resolveFilePath(baseDir: string, value: unknown, label: string) {
  const file = String(value ?? "").trim();
  if (!file) throw new Error(`missing ${label} file`);
  return path.isAbsolute(file) ? file : path.resolve(baseDir, file);
}
function resolveRootDir() {
  const cwd = process.cwd();
  if (path.basename(cwd) === "server" && existsSync(path.join(cwd, "package.json"))) return path.resolve(cwd, "..");
  if (existsSync(path.join(cwd, "client", "package.json")) && existsSync(path.join(cwd, "server", "package.json"))) return cwd;
  if (existsSync(path.join(cwd, "fe", "client", "package.json")) && existsSync(path.join(cwd, "fe", "server", "package.json"))) return path.join(cwd, "fe");
  if (existsSync(path.join(cwd, "server", "package.json"))) return cwd;
  return path.resolve(cwd, "..");
}
function parseArgs(args: string[]) {
  const parsed: Record<string, string> = {};
  const aliases: Record<string, string> = {
    "log-dir": "logDir", "derived-dir": "derivedDir", "event-journal-dir": "eventJournalDir", "stream-state-dir": "streamStateDir",
    "timeline-live-file": "timelineLiveFile", "timeline-events-dir": "timelineEventsDir", "timeline-checkpoint-dir": "timelineCheckpointDir",
    "metrics-raw-dir": "metricsRawDir", "metrics-rollup-dir": "metricsRollupDir",
    "topology-live-file": "topologyLiveFile", "topology-checkpoint-dir": "topologyCheckpointDir", "topology-updates-dir": "topologyUpdatesDir",
    "host": "host", "port": "port", "max-events": "maxEvents", "max-timeline-rows": "maxTimelineRows", "streams-patch-interval-ms": "streamsPatchIntervalMs",
    "ws-max-buffered-bytes": "wsMaxBufferedBytes", "http-access-log": "httpAccessLog", "metrics-chunk-log": "metricsChunkLog", "events-query-debug-log": "eventsQueryDebugLog", "diagnostic-log": "diagnosticLog"
  };
  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (!arg.startsWith("--")) continue;
    const [rawKey, ...rest] = arg.slice(2).split("=");
    const inlineValue = rest.join("=");
    const value = inlineValue || (args[index + 1]?.startsWith("--") ? "" : args[index + 1] ?? "");
    const key = aliases[rawKey];
    if (!key || !value) continue;
    parsed[key] = value;
    if (!inlineValue) index += 1;
  }
  return parsed;
}
function toBool(value: unknown, defaultValue: boolean) {
  if (value === undefined || value === null || value === "") return defaultValue;
  const normalized = String(value).trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(normalized)) return true;
  if (["0", "false", "no", "off"].includes(normalized)) return false;
  return defaultValue;
}
