export type DashboardViewType = "streams" | "detail" | "timeline" | "topology" | "events";

export type DashboardCell = {
  id: string;
  title: string;
  viewType: DashboardViewType;
  grid: { x: number; y: number; w: number; h: number };
  params?: Record<string, unknown>;
