import { useEffect, useState, type FormEvent } from "react";
import { getProtocolMapSettings, saveProtocolMapSettings } from "../api/client";
import type { ProtocolMapDocument, ProtocolMapResponse, ProtocolRule } from "../types/api";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type Row = ProtocolRule & { target: "endpoint" | "host"; value: string; port: string; vlanMode: "any" | "untagged" | "id"; vlanId: string };

const modes = ["all", "configured_only", "configured_plus_other"] as const;

export function ProtocolMapPane() {
  const [settings, setSettings] = useState<ProtocolMapResponse | null>(null);
  const [path, setPath] = useState("");
  const [mode, setMode] = useState<ProtocolMapDocument["observe_mode"]>("all");
  const [rows, setRows] = useState<Row[]>([]);
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");
  const locked = mode === "all";

  const load = () => {
    setState("loading");
    void getProtocolMapSettings().then((next) => {
      setSettings(next); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setState("idle"); setMessage("");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to load protocol map"); });
  };
  useEffect(load, []);

  const updateRow = (index: number, patch: Partial<Row>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
  const addRow = () => setRows((current) => [...current, { enabled: true, observe: true, proto: "RTP", target: "endpoint", value: "", port: "", vlanMode: "any", vlanId: "" }]);

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving"); setMessage("");
    const document: ProtocolMapDocument = { observe_mode: mode, protocols: rows.map(fromRow) };
    void saveProtocolMapSettings(settings.revision, path, document).then((next) => {
      setSettings(next); setPath(next.path); setMode(next.document.observe_mode ?? "all"); setRows(next.document.protocols.map(toRow)); setState("saved"); setMessage("Saved. Restart STM to apply the new protocol map.");
    }).catch((error: unknown) => { setState("error"); setMessage(error instanceof Error ? error.message : "Failed to apply protocol map"); });
  };

  return <PaneFrame className="maintenance-frame protocol-map-frame" header={<PaneHeader title="Protocol map" meta="STM classification and observation rules" actions={<button type="button" className="maintenance-secondary-button" onClick={load} disabled={state === "loading" || state === "saving"}>Reload</button>} />}>
    <form className="maintenance-form" onSubmit={submit}>
      <div className="maintenance-intro">Apply writes the selected protocol map and updates STM&apos;s config reference. STM restart is required before the change takes effect.</div>
      <section className="maintenance-section"><div className="maintenance-section-copy"><h2>Protocol map file</h2><p>Path relative to the STM unified config file.</p></div><div className="protocol-map-controls"><label>Path<input value={path} disabled={state === "saving"} onChange={(event) => setPath(event.target.value)} /></label><label>Observe mode<select value={mode} disabled={state === "saving"} onChange={(event) => setMode(event.target.value as ProtocolMapDocument["observe_mode"])}>{modes.map((item) => <option key={item} value={item}>{item}</option>)}</select></label></div></section>
      {locked && <div className="protocol-map-notice">all observes every classified stream. Saved rules remain available but cannot be edited in this mode.</div>}
      <section className="maintenance-section"><div className="maintenance-table-wrap"><table className="maintenance-table protocol-map-table"><thead><tr><th>#</th><th>Enabled</th><th>Target</th><th>Address / domain</th><th>Port</th><th>VLAN</th><th>Protocol</th><th>RTP FEC</th><th>Stream name</th><th /></tr></thead><tbody>{rows.map((row, index) => <tr key={index}><td>{index + 1}</td><td><button type="button" role="switch" aria-checked={row.enabled !== false} className={`maintenance-switch ${row.enabled !== false ? "is-on" : "is-off"}`} disabled={locked || state === "saving"} onClick={() => updateRow(index, { enabled: row.enabled === false })}>{row.enabled === false ? "Off" : "On"}</button></td><td><select value={row.target} disabled={locked || state === "saving" || row.proto !== "HLS"} onChange={(event) => updateRow(index, { target: event.target.value as Row["target"], value: "", port: "" })}><option value="endpoint">Endpoint</option><option value="host">Host</option></select></td><td><input value={row.value} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { value: event.target.value })} placeholder={row.target === "host" ? "media.example.com" : "239.1.1.1"} /></td><td>{row.target === "endpoint" && <input type="number" min="1" max="65535" value={row.port} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { port: event.target.value })} />}</td><td><select value={row.vlanMode} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanMode: event.target.value as Row["vlanMode"] })}><option value="any">Any</option><option value="untagged">Untagged</option><option value="id">ID</option></select>{row.vlanMode === "id" && <input type="number" min="0" max="4094" value={row.vlanId} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanId: event.target.value })} />}</td><td><select value={row.proto} disabled={locked || state === "saving"} onChange={(event) => { c