      <footer className="maintenance-actions"><span className={`maintenance-message maintenance-message-${state}`} role="status">{state === "loading" ? "Loading protocol map…" : message}</span><button type="submit" className="maintenance-save-button" disabled={!settings || state === "loading" || state === "saving"}>{state === "saving" ? "Applying…" : "Apply"}</button></footer>
    </form>
  </PaneFrame>;
}

function toRow(rule: ProtocolRule): Row {
  const endpoint = first(rule.endpoints); const host = first(rule.hosts) || first(rule.domains); const target = host ? "host" : "endpoint"; const split = endpoint ? splitEndpoint(endpoint) : { value: host ?? "", port: "" }; const vlan = rule.vlan === null ? { vlanMode: "untagged" as const, vlanId: "" } : rule.vlan === undefined ? { vlanMode: "any" as const, vlanId: "" } : { vlanMode: "id" as const, vlanId: String(rule.vlan) };
  return { ...rule, target, value: split.value, port: split.port, ...vlan };
}
function fromRow(row: Row): ProtocolRule {
  const { target, value, port, vlanMode, vlanId, ...rule } = row; const next: ProtocolRule = { ...rule, observe: rule.observe ?? true, enabled: rule.enabled !== false, proto: rule.proto, ...(vlanMode === "untagged" ? { vlan: null } : vlanMode === "id" ? { vlan: Number(vlanId) } : {}) };
  if (target === "host") next.hosts = [value.trim()]; else next.endpoints = [`${formatHost(value.trim())}:${port}`];
  if (next.proto !== "RTP") delete next.fec;
  return next;
}
function first(value: string | string[] | undefined) { return typeof value === "string" ? value : value?.[0] ?? ""; }
function splitEndpoint(endpoint: string) { const ipv6 = endpoint.match(/^\[(.*)]:(\d+)$/); if (ipv6) return { value: ipv6[1], port: ipv6[2] }; const index = endpoint.lastIndexOf(":"); return index > 0 ? { value: endpoint.slice(0, index), port: endpoint.slice(index + 1) } : { value: endpoint, port: "" }; }
function formatHost(value: string) { return value.includes(":") && !value.startsWith("[") ? `[${value}]` : value; }
