      {locked && <div className="protocol-map-notice">all observes every classified stream. Saved rules remain available but cannot be edited in this mode.</div>}
      <section className="maintenance-section"><div className="maintenance-table-wrap"><table className="maintenance-table protocol-map-table"><thead><tr><th>#</th><th>Enabled</th><th>Protocol</th><th>Target</th><th>Address / domain</th><th>Port</th><th>VLAN</th><th>Stream name</th><th /></tr></thead><tbody>{rows.map((row, index) => <tr key={index}><td>{index + 1}</td><td><button type="button" role="switch" aria-checked={row.enabled !== false} className={`maintenance-switch ${row.enabled !== false ? "is-on" : "is-off"}`} disabled={locked || state === "saving"} onClick={() => updateRow(index, { enabled: row.enabled === false })}>{row.enabled === false ? "Off" : "On"}</button></td><td><select value={row.proto} disabled={locked || state === "saving"} onChange={(event) => { const proto = event.target.value as Row["proto"]; updateRow(index, { proto, target: proto === "HLS" ? row.target : "endpoint", fec: proto === "RTP-FEC" }); }}><option value="RTP">RTP</option><option value="RTP-FEC">RTP-FEC</option><option value="SRT">SRT</option><option value="HLS">HLS</option></select></td><td><select value={row.target} disabled={locked || state === "saving" || row.proto !== "HLS"} onChange={(event) => updateRow(index, { target: event.target.value as Row["target"], value: "", port: "" })}><option value="endpoint">Endpoint</option><option value="host">Host</option></select></td><td><input value={row.value} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { value: event.target.value })} placeholder={row.target === "host" ? "media.example.com" : "239.1.1.1"} /></td><td>{row.target === "endpoint" && <input type="number" min="1" max="65535" value={row.port} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { port: event.target.value })} />}</td><td><select value={row.vlanMode} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanMode: event.target.value as Row["vlanMode"] })}><option value="any">Any</