import { matchesSearch } from "./components/search";

type ExpandLevel = "interface" | "proto" | "stream" | "flow";
type DetailMode = "overview" | "detail";
type MainTab = "dashboard" | "streams" | "detail" | "timeline" | "topology" | "events" | "maintenance" | "protocol-map";
type MenuItem = {
  key: MainTab;
  icon: string;
  label: string;
  hint: string;
};
type StandaloneView = "streams" | "timeline" | "events" | "detail" | null;

const MENU_ITEMS: MenuItem[] = [
  { key: "dashboard", icon: "◫", label: "Dashboard", hint: "Overview panels" },
  { key: "streams", icon: "≈", label: "Streams", hint: "Tree and filters" },
  { key: "detail", icon: "▤", label: "Detail", hint: "Metrics and flows" },
  { key: "timeline", icon: "▥", label: "Timeline", hint: "History bands" },
  { key: "topology", icon: "◇", label: "Topology", hint: "Network map" },
  { key: "events", icon: "!", label: "Events", hint: "Alerts and logs" },
  { key: "maintenance", icon: "⚙", label: "Maintenance", hint: "Shared runtime settings" },
  { key: "protocol-map", icon: "⌘", label: "Protocol map", hint: "STM protocol classification" }
];
const RANGE_OPTIONS = ["24h", "12h", "6h", "3h", "1h", "30m", "10m", "5m"];
const DEFAULT_DASHBOARD_LAYOUT: DashboardLayout = {
  id: "default",
  name: "Default dashboard",
  columns: 24,
  rowHeight: 32,
import { StatusBadge } from "./StatusBadge";

type AppContextBarProps = {
  title?: string;
  updatedLabel: string;
  socketState: string;
  totalStreams?: number;
  liveLabel: string;
  liveTone: "success" | "warning";
  onToggleLive: () => void;
  onToggleTheme: () => void;
  theme: "light" | "dark";
  compact?: boolean;
};

export function AppContextBar({
  title = "Media Stream Monitor",
  updatedLabel,
  socketState,
  totalStreams,
  liveLabel,
  liveTone,
  onToggleLive,
  onToggleTheme,
  theme,
  compact = false
}: AppContextBarProps) {
  return (
    <header className={`app-context-bar ${compact ? "app-context-bar-compact" : ""}`}>
      <div className="app-context-identity">
        <strong>{title}</strong>
        <span>{updatedLabel}</span>
      </div>
      <div className="app-context-status" aria-label="Application status">
        {totalStreams !== undefined && <StatusBadge>{totalStreams} streams</StatusBadge>}
        <StatusBadge>{socketState}</StatusBadge>
        <button type="button" className={`context-live-toggle is-${liveTone}`} onClick={onToggleLive} title="Toggle live updates">
          <span aria-hidden="true" />
          {liveLabel}
        </button>
        <button
          type="button"
          className="context-theme-toggle"
          onClick={onToggleTheme}
          title={theme === "light" ? "Switch to dark theme" : "Switch to light theme"}
          aria-label={theme === "light" ? "Switch to dark theme" : "Switch to light theme"}
        >
          {theme === "light" ? "Dark" : "Light"}
        </button>
      </div>
    </header>
  );
}
type SearchInputProps = {
  value: string;
  onChange: (value: string) => void;
  placeholder: string;
  label: string;
  className?: string;
};

export function SearchInput({ value, onChange, placeholder, label, className = "" }: SearchInputProps) {
  return (
    <label className={`search-input ${className}`.trim()}>
      <span aria-hidden="true">⌕</span>
      <input value={value} onChange={(event) => onChange(event.target.value)} placeholder={placeholder} aria-label={label} />
      {value && (
        <button type="button" className="search-clear" onClick={() => onChange("")} aria-label={`Clear ${label}`} title={`Clear ${label}`}>
          ×
        </button>
      )}
    </label>
  );
}
