import { useEffect, useState, type FormEvent } from "react";
import { getMaintenanceSettings, saveMaintenanceSettings } from "../api/client";
import type { AppConfig, MaintenanceSettingsResponse } from "../types/api";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type MaintenancePaneProps = {
  refreshToken: number;
  onApplied: (config: AppConfig) => void;
};

export function MaintenancePane({ refreshToken, onApplied }: MaintenancePaneProps) {
  const [settings, setSettings] = useState<MaintenanceSettingsResponse | null>(null);
  const [draft, setDraft] = useState<AppConfig | null>(null);
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");

  useEffect(() => {
    let cancelled = false;
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      if (cancelled) return;
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      if (cancelled) return;
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
    return () => { cancelled = true; };
  }, [refreshToken]);

  const reload = () => {
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
  };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings || !draft) return;
    setState("saving");
    setMessage("");
    void saveMaintenanceSettings(settings.revision, draft).then((next) => {
      setSettings(next);
      setDraft(next.values);
      onApplied(next.values);
      setState("saved");
      setMessage("Saved and applied to all connected clients.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to save settings");
    });
  };

  return (
    <PaneFrame
      className="maintenance-frame"
      header={<PaneHeader
        title="Maintenance"
        meta="Shared frontend runtime settings"
        actions={<button type="button" className="maintenance-secondary-button" onClick={reload} disabled={state === "loading" || state === "saving"}>Reload</button>}
      />}
    >
      <form className="maintenance-form" onSubmit={submit}>
        <div className="maintenance-intro">Changes are validated by the server, persisted for the next restart, and applied immediately to every connected client.</div>
        {settings?.sections.map((section) => (
          <section key={section.id} className="maintenance-section">
            <div className="maintenance-section-copy">
              <h2>{section.label}</h2>
              {section.description && <p>{section.description}</p>}
            </div>
            <div className="maintenance-table-wrap">
              <table className="maintenance-table">
                <thead><tr><th>Parameter</th><th>Value</th><th>Range</th><th>Apply</th></tr></thead>
                <tbody>
                  {section.settings.map((setting) => {
                    const value = draft?.[setting.key];
                    return (
                      <tr key={setting.key}>
                        <th scope="row"><span>{setting.label}</span>{setting.description && <small>{setting.description}</small>}</th>
                        <td>
                          {setting.type === "boolean" ? (
                            <button
                              type="button"
                              role="switch"
                              aria-checked={Boolean(value)}
                              className={`maintenance-switch ${value ? "is-on" : "is-off"}`}
                              disabled={!draft || state === "saving"}
                              onClick={() => setDraft((current) => current ? { ...current, [setting.key]: !current[setting.key] } : current)}
                            >
                              <span className="maintenance-switch-track" aria-hidden="true"><span className="maintenance-switch-thumb" /></span>
                              <span>{value ? "On" : "Off"}</span>
                            </button>
                          ) : setting.type === "select" ? (
                            <select value={String(value ?? "")} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)}>
                              {setting.options?.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                            </select>
                          ) : (
                            <input type="number" value={String(value ?? "")} min={setting.min} max={setting.max} step={setting.step ?? 1} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)} />
                          )}
                          {setting.unit && <span className="maintenance-unit">{setting.unit}</span>}
                        </td>
                        <td>{setting.type === "boolean" ? "—" : `${setting.min ?? "—"}–${setting.max ?? "—"}`}</td>
                        <td><span className={`maintenance-apply maintenance-apply-${setting.apply}`}>{setting.apply}</span></td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </section>
        ))}
        <footer className="maintenance-actions">
          <span className={`maintenance-message maintenance-message-${state}`} role="status">{state === "loading" ? "Loading settings…" : message}</span>
          <button type="submit" className="maintenance-save-button" disabled={!draft || state === "loading" || state === "saving"}>{state === "saving" ? "Saving…" : "Save and apply"}</button>
        </footer>
import { Responsive, useContainerWidth, noCompactor, type Compactor, type Layout, type LayoutItem } from "react-grid-layout";
import { useCallback, useMemo, useState, type ReactNode, type Ref } from "react";
import type { DashboardBreakpoint, DashboardCell, DashboardLayout, DashboardResponsiveLayouts } from "../types/api";

const fixedGridCompactor: Compactor = {
  ...noCompactor,
  preventCollision: true
};

type DashboardGridProps = {
  dashboard: DashboardLayout;
  editing: boolean;
  renderCell: (cell: DashboardCell) => ReactNode;
  renderCellActions?: (cell: DashboardCell) => ReactNode;
  onLayoutsChange: (layouts: DashboardResponsiveLayouts) => void;
  onUpdateCell: (cellId: string, updater: (cell: DashboardCell) => DashboardCell) => void;
  onRemoveCell: (cellId: string) => void;
};

export function DashboardGrid({
  dashboard,
  editing,
  renderCell,
  renderCellActions,
  onLayoutsChange,
  onUpdateCell,
  onRemoveCell
}: DashboardGridProps) {
  const { width, containerRef, mounted } = useContainerWidth({ initialWidth: 1280 });
  const [activeBreakpoint, setActiveBreakpoint] = useState<DashboardBreakpoint>(breakpointForWidth(width));
  const cellsByBreakpoint = useMemo(() => buildResponsiveCells(dashboard.cells, dashboard.layouts), [dashboard.cells, dashboard.layouts]);
  const activeCells = cellsByBreakpoint[activeBreakpoint] ?? dashboard.cells;
  const layouts = useMemo(() => Object.fromEntries(
    (Object.keys(BREAKPOINT_COLUMNS) as DashboardBreakpoint[]).map((breakpoint) => [
      breakpoint,
      cellsByBreakpoint[breakpoint].map(toLayoutItem)
    ])
  ) as unknown as Record<DashboardBreakpoint, Layout>, [cellsByBreakpoint]);

  const handleLayoutChange = useCallback((_layout: Layout, nextLayouts: Partial<Record<string, Layout>>) => {
    if (!editing) return;
    const normalized = {} as DashboardResponsiveLayouts;
    for (const breakpoint of Object.keys(BREAKPOINT_COLUMNS) as DashboardBreakpoint[]) {
      const layout = nextLayouts[breakpoint];
      if (layout) normalized[breakpoint] = mergeLayoutCells(cellsByBreakpoint[breakpoint], layout);
    }
    onLayoutsChange(normalized);
  }, [editing, cellsByBreakpoint, onLayoutsChange]);

  return (
    <div ref={containerRef as unknown as Ref<HTMLDivElement>} className={`dashboard-rgl-shell ${editing ? "is-editing" : "is-viewing"}`}>
      {mounted && (
        <Responsive
          className="dashboard-rgl"
          width={width}
          layouts={layouts}
          breakpoints={BREAKPOINTS}
          cols={BREAKPOINT_COLUMNS}
          rowHeight={dashboard.rowHeight}
          margin={[10, 10]}
          containerPadding={[0, 0]}
          dragConfig={{
            enabled: editing,
            handle: ".dashboard-drag-handle",
            cancel: ".dashboard-cell-body, .dashboard-cell-actions, input, select, .dashboard-cell-remove, a"
          }}
          resizeConfig={{
            enabled: editing,
            handles: ["se"]
          }}
          compactor={fixedGridCompactor}
          autoSize
          onBreakpointChange={(breakpoint) => setActiveBreakpoint(toDashboardBreakpoint(breakpoint))}
          onLayoutChange={handleLayoutChange}
        >
          {activeCells.map((cell) => (
            <section key={cell.id} className={`dashboard-cell dashboard-cell-${cell.viewType}`}>
              <header className="pane-header pane-header-compact dashboard-cell-header">
                {editing ? <>
                  <button type="button" className="dashboard-drag-handle" aria-label="Move cell" title="Drag to move">⋮⋮</button>
                  <input
                    value={cell.title}
                    onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, title: event.target.value }))}
                    aria-label="Cell title"
                  />
                  <select
                    value={cell.viewType}
                    onChange={(event) => onUpdateCell(cell.id, (current) => ({ ...current, viewType: event.target.value as DashboardCell["viewType"], title: titleForDashboardView(event.target.value as DashboardCell["viewType"]) }))}
                    aria-label="Cell view type"
                  >
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { FlowListItem, InterfaceListItem, StreamListItem } from "../types/api";
import { Sparkline } from "./Sparkline";
import { formatBitrate, formatRelativeTime } from "./format";

type StreamTableProps = {
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  selectedStreamKey: string | null;
  selectedFlowKey: string | null;
  selectedInterfaceKey: string | null;
  overviewMode?: boolean;
  expandLevel?: "interface" | "proto" | "stream" | "flow";
  onSelectInterface: (interfaceKey: string) => void;
  onSelectStream: (streamKey: string) => void;
