option><option value="untagged">Untagged</option><option value="id">ID</option></select>{row.vlanMode === "id" && <input type="number" min="0" max="4094" value={row.vlanId} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { vlanId: event.target.value })} />}</td><td><input value={row.stream_name ?? ""} disabled={locked || state === "saving"} onChange={(event) => updateRow(index, { stream_name: event.target.value })} /></td><td><button type="button" className="maintenance-secondary-button icon-only" disabled={locked || state === "saving"} onClick={() => removeRow(index)} aria-label="Delete protocol rule" title="Delete protocol rule"><Icon name="delete" size={16} /></button></td></tr>)}</tbody></table></div><div className="protocol-map-row-actions"><button type="button" className="maintenance-secondary-button button-with-icon" disabled={locked || state === "saving"} onClick={addRow}><Icon name="add" size={16} />Add row</button></div></section>
