			return -1;
		}

		rule r;
		r.id = entry["id"].get<std::string>();
		r.metric = entry["metric"].get<std::string>();
		if(entry.contains("target") && entry["target"].is_string()) r.target = entry["target"].get<std::string>();
		if(entry.contains("proto") && entry["proto"].is_string()) r.proto = entry["proto"].get<std::string>();
		if(entry.contains("type") && entry["type"].is_string()) r.type = parse_rule_type(entry["type"].get<std::string>());
		if(entry.contains("operator") && entry["operator"].is_string()) r.op = parse_compare_op(entry["operator"].get<std::string>());
		if(entry.contains("error_threshold")) r.error_threshold = entry["error_threshold"].get<double>();
		if(entry.contains("recover_threshold")) r.recover_threshold = entry["recover_threshold"].get<double>();
		else r.recover_threshold = r.error_threshold;
		if(entry.contains("delta_threshold")) r.delta_threshold = entry["delta_threshold"].get<double>();
		if(entry.contains("recover_after_sec")) r.recover_after_sec = entry["recover_after_sec"].get<double>();
		if(entry.contains("severity") && entry["severity"].is_string()) r.severity = entry["severity"].get<std::string>();
		r.enabled = read_bool(entry, "enabled", true);

		m_rules.push_back(std::move(r));
		}
		catch(const std::exception &e) {
			std::cerr << "alert_evaluator: invalid alert entry: " << e.what() << std::endl;
			return -1;
		}
	}

	return 0;
}

void alert_evaluator::evaluate(double now, const json::array_t &metrics, const json::array_t &interfaces) {
	for(const auto &entry : metrics) {
		if(!entry.is_object()) {
			continue;
		}
		for(const auto &r : m_rules) {
			if(!r.enabled) {
				continue;
			}
			evaluate_entry(now, r, entry, false);
		}
	}
	for(const auto &entry : interfaces) {
		if(!entry.is_object()) {
			continue;
		}
		for(const auto &r : m_rules) {
			if(!r.enabled) {
				continue;
		entry["last_seen_time"] = s.last_seen_time;
		out.push_back(std::move(entry));
	}
	return out;
}

void alert_evaluator::evaluate_entry(double now, const rule &r, const json &entry, bool is_interface) {
	if(!matches_target(r, entry, is_interface)) {
		return;
	}
	auto value = metric_value(entry, r.metric);
	if(!value.has_value() || !std::isfinite(*value)) {
		return;
	}

	const auto state_key = make_state_key(r, entry, is_interface);
	auto &s = m_states[state_key];
	s.last_seen_time = now;

	switch(r.type) {
	case rule_type::threshold:
		evaluate_threshold(now, r, entry, is_interface, state_key, s, *value);
		break;
	case rule_type::counter_delta:
		evaluate_counter_delta(now, r, entry, is_interface, state_key, s, *value);
		break;
	}
}

void alert_evaluator::evaluate_threshold(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
	if(!s.active) {
		if(compare(value, r.op, r.error_threshold)) {
			s.active = true;
			s.last_error_time = now;
			json detail{
				{"metric", r.metric},
				{"value", value},
				{"threshold", r.error_threshold},
				{"operator", "error"},
			};
			update_active_state(now, r, entry, is_interface, s, value, detail);
			emit_alert(now, r, entry, is_interface, "detected", value, std::move(detail));
		}
		return;
	}

	if(!compare(value, r.op, r.recover_threshold)) {
		s.active = false;
		emit_alert(now, r, entry, is_interface, "recovered", value, json{
			{"metric", r.metric},
			{"value", value},
			{"threshold", r.recover_threshold},
			{"operator", "recover"},
		});
		return;
	}

	update_active_state(now, r, entry, is_interface, s, value, json{
		{"metric", r.metric},
		{"value", value},
		{"threshold", r.error_threshold},
		{"operator", "error"},
	});
}

void alert_evaluator::evaluate_counter_delta(double now, const rule &r, const json &entry, bool is_interface, const std::string &, state &s, double value) {
	if(!s.has_last_value) {
		s.has_last_value = true;
		s.last_value = value;
		return;
	}

	const double delta = value - s.last_value;
	s.last_value = value;
	if(compare(delta, r.op, r.delta_threshold)) {
		json detail{
			{"metric", r.metric},
			{"value", value},
			{"delta", delta},
			{"threshold", r.delta_threshold},
		};
		if(!s.active) {
			s.active = true;
			emit_alert(now, r, entry, is_interface, "detected", value, detail);
		}
		s.last_error_time = now;
		update_active_state(now, r, entry, is_interface, s, value, std::move(detail));
		return;
	}

	if(s.active && (now - s.last_error_time) >= r.recover_after_sec) {
		s.active = false;
		emit_alert(now, r, entry, is_interface, "recovered", value, json{
			{"metric", r.metric},
			{"value", value},
			{"delta", delta},
			{"recover_after_sec", r.recover_after_sec},
		});
	}
}

void alert_evaluator::emit_alert(double now, const rule &r, const json &entry, bool is_interface, std::string action, double value, json detail) {
	detail["alert_id"] = r.id;
	detail["severity"] = r.severity;
	detail["action"] = action;
	detail["value"] = value;
	}
	ss << "|proto=" << json_string_or_empty(entry, "proto")
	   << "|stream=" << json_string_or_empty(entry, "stream_key");
	const auto flow_key = json_string_or_empty(entry, "flow_key");
	if(!flow_key.empty()) {
		ss << "|flow=" << flow_key;
	}
	return ss.str();
}

json alert_evaluator::make_target_source(const rule &r, const json &entry, bool is_interface) {
	json source{
		{"alert_id", r.id},
		{"severity", r.severity},
		{"target", is_interface ? "interface" : (entry.contains("flow_key") ? "flow" : "stream")},
	};
	for(const auto &key : {"proto", "stream_key", "flow_key", "interface_id", "name"}) {
		if(entry.contains(key)) {
			source[key] = entry[key];
		}
	}
	return source;
}

alert_evaluator::rule_type alert_evaluator::parse_rule_type(const std::string &value) {
	if(value == "threshold") return rule_type::threshold;
	if(value == "counter_delta") return rule_type::counter_delta;
	throw std::runtime_error("unknown alert rule type: " + value);
}

alert_evaluator::compare_op alert_evaluator::parse_compare_op(const std::string &value) {
	if(value == ">") return compare_op::gt;
	if(value == ">=") return compare_op::ge;
	if(value == "<") return compare_op::lt;
	if(value == "<=") return compare_op::le;
	if(value == "==") return compare_op::eq;
	if(value == "!=") return compare_op::ne;
	throw std::runtime_error("unknown alert operator: " + value);
}

