void alert_evaluator::update_active_state(double now, const rule &r, const json &entry, bool is_interface, state &s, double value, json detail) {
	detail["alert_id"] = r.id;
	detail["severity"] = r.severity;
	detail["value"] = value;
	s.source = make_target_source(r, entry, is_interface);
	s.detail = std::move(detail);
	s.last_value = value;
	s.last_seen_time = now;
}

std::optional<double> alert_evaluator::metric_value(const json &entry, const std::string &path) {
	const json *cur = &entry;
	for(const auto &part : split_path(path)) {
		if(!cur->is_object() || !cur->contains(part)) {
			return std::nullopt;
		}
		cur = &(*cur)[part];
	}
	if(cur->is_number()) {
		return cur->get<double>();
	}
	return std::nullopt;
}

bool alert_evaluator::compare(double lhs, compare_op op, double rhs) {
	switch(op) {
	case compare_op::gt: return lhs > rhs;
	case compare_op::ge: return lhs >= rhs;
	case compare_op::lt: return lhs < rhs;
	case compare_op::le: return lhs <= rhs;
	case compare_op::eq: return lhs == rhs;
	case compare_op::ne: return lhs != rhs;
	}
	return false;
}

