void flow::emit_segment_response(const info &i, double response_time) {
	json detail{
		{"role", i.role},
		{"path", i.path},
		{"status_code", i.status_code},
		{"effective_status_code", i.effective_status_code},
		{"status_source", i.status_source},
		{"payload_seen", i.payload_seen},
		{"inferred_success", i.inferred_success},
		{"response_time_sec", response_time},
		{"endpoint", {
			{"host", i.host},
			{"port", i.port},
			{"path", i.path},
		}},
	};
	if(i.has_content_length) {
		detail["download_bytes"] = i.content_length;
	}
	if(i.has_request_time) {
		detail["request_time"] = i.request_time;
	}
	detail["severity"] = i.effective_status_code >= 400 ? "warning" : "info";
	trace(3, "hls: segment_response emitted status=%u effective_status=%u source=%s inferred=%d path=%s response_time=%.6f bytes=%llu",
	      static_cast<unsigned>(i.status_code),
	      static_cast<unsigned>(i.effective_status_code),
	      i.status_source.c_str(),
	      i.inferred_success ? 1 : 0,
	      i.path.c_str(),
	      response_time,
	      static_cast<unsigned long long>(i.content_length));
	m_events.emit(make_event(i.time_epoch, "segment_response", std::move(detail)));
}

int flow::append_metrics(double now, json::array_t &out) {
	const auto bitrate = m_metrics.bitrate.snapshot_at(now);
	json j = stream_json::make_flow_metrics_base(proto_name,
	                                             m_fid.interface_id,
	                                             m_interface_name,
	                                             m_stream_key,
	                                             m_flow_key,
	                                             m_fid.vlan);
	j["role"] = m_fid.role;
	j["endpoint"] = {
		{"host", m_fid.host},
		{"port", m_fid.port},
	};
	j["last_path"] = m_last_path;
	j["last_status_code"] = m_last_status_code;
	j["last_effective_status_code"] = m_last_effective_status_code;
	j["last_status_source"] = m_last_status_source;
	j["last_inferred_success"] = m_last_inferred_success;
	j["last_response_time_sec"] = m_last_response_time;
	j.update(json{
		{"request_count", { {"window", m_metrics.request_count.count()}, {"total", m_metrics.request_count.total()} }},
		{"response_count", { {"window", m_metrics.response_count.count()}, {"total", m_metrics.response_count.total()} }},
		{"error_count", { {"window", m_metrics.error_count.count()}, {"total", m_metrics.error_count.total()} }},
		{"download_bytes", { {"window", m_metrics.download_bytes.count()}, {"total", m_metrics.download_bytes.total()} }},
		{"bitrate", {
			{"bps", bitrate.bps},
			{"count", bitrate.stats.count},
			{"min", bitrate.stats.min},
			{"max", bitrate.stats.max},
			{"avg", bitrate.stats.avg()},
		}},
		{"request_interval", {
			{"seconds", m_metrics.request_interval.value()},
			{"count", m_metrics.request_interval.stats().count},
			{"min", m_metrics.request_interval.stats().min},
			{"max", m_metrics.request_interval.stats().max},
			{"avg", m_metrics.request_interval.stats().avg()},
		}},
		{"download_time", stats_json(m_metrics.download_time)},
		{"status", status_json(m_metrics.status)},
		{"duration", {
			{"seconds", m_metrics.lifetime.duration_sec()},
			{"first_seen", m_metrics.lifetime.first_seen()},
			{"last_seen", m_metrics.lifetime.last_seen()},
		}},
	});

	out.push_back(std::move(j));
	m_metrics_emitted = true;
	m_metrics.request_count.reset();
	m_metrics.response_count.reset();
	m_metrics.error_count.reset();
	m_metrics.download_bytes.reset();
	m_metrics.bitrate.clear_stats();
	m_metrics.request_interval.clear_stats();
	m_metrics.download_time.clear();
	m_metrics.status.reset_window();
	return 0;
}

json flow::to_list_json(double now) const {
	(void)now;
	json j = stream_json::make_flow_list_base(m_flow_key,
	                                         m_fid.interface_id,
	                                         m_interface_name,
	                                         m_fid.vlan);
	j["role"] = m_fid.role;
	j["endpoint"] = {
		{"host", m_fid.host},
		{"port", m_fid.port},
	};
	j["last_path"] = m_last_path;
	j["last_status_code"] = m_last_status_code;
	j["last_effective_status_code"] = m_last_effective_status_code;
	j["last_status_source"] = m_last_status_source;
	j["last_inferred_success"] = m_last_inferred_success;
	j["last_response_time_sec"] = m_last_response_time;
	j["last_seen"] = last_seen();
	return j;
}

int flow::update_events(double now) {
	const auto update = m_error_state.update(now, m_error_window);
	if(update.occurred) {
		m_events.emit(make_event(now, m_fid.role + "_error_occurred", json{
			{"role", m_fid.role},
			{"window_count", update.window_count},
	if(ifs.good() == false) {
		return false;
	}

	ifs >> value;
	return ifs.fail() == false;
}

bool interface::update_stat(const char *name, counter_value &counter) {
	std::uint64_t value = 0;
	if(read_stat(name, value) == false) {
		return false;
	}

	counter.update(value);
	return true;
}

void interface::update_link_info() {
	std::int64_t speed_mbps = 0;
	m_link.has_speed_mbps = read_sysfs_int64("speed", speed_mbps) && speed_mbps > 0;
	m_link.speed_mbps = m_link.has_speed_mbps ? static_cast<std::uint64_t>(speed_mbps) : 0;

	m_link.has_duplex = read_sysfs_string("duplex", m_link.duplex);
	m_link.has_operstate = read_sysfs_string("operstate", m_link.operstate);

