int stream::observe_transport(const flow_id &fid, const info &i) {
	touch(i.time_epoch);
	m_metrics.lifetime.update(i.time_epoch);
	const std::uint64_t bytes = i.tcp_len > 0 ? i.tcp_len : i.frame_len;
	if(bytes > 0) {
		m_metrics.download_bytes.add(bytes);
		m_metrics.bitrate.update(i.time_epoch, bytes);
	}

	if(m_has_playlist) {
		m_playlist_last_seen = i.time_epoch;
	}

	auto it = m_flows.find(fid);
	if(it == m_flows.end()) {
		it = m_flows.emplace(fid, std::make_unique<flow>(m_sid, fid, i.interface_name, m_cfg.timeout.error_recovery_sec, m_events)).first;
		it->second->emit_detected(i.time_epoch);
	}
	return it->second->observe_transport(i);
}

