import { useEffect, useState, type FormEvent } from "react";
import { getMaintenanceSettings, saveMaintenanceSettings } from "../api/client";
import type { AppConfig, MaintenanceSettingsResponse } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type MaintenancePaneProps = {
  refreshToken: number;
  onApplied: (config: AppConfig) => void;
};

export function MaintenancePane({ refreshToken, onApplied }: MaintenancePaneProps) {
  const [settings, setSettings] = useState<MaintenanceSettingsResponse | null>(null);
  const [draft, setDraft] = useState<AppConfig | null>(null);
  const [state, setState] = useState<"loading" | "idle" | "saving" | "saved" | "error">("loading");
  const [message, setMessage] = useState("");

  useEffect(() => {
    let cancelled = false;
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      if (cancelled) return;
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      if (cancelled) return;
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
    return () => { cancelled = true; };
  }, [refreshToken]);

  const reload = () => {
    setState("loading");
    void getMaintenanceSettings().then((next) => {
      setSettings(next);
      setDraft(next.values);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load settings");
    });
  };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings || !draft) return;
    setState("saving");
    setMessage("");
    void saveMaintenanceSettings(settings.revision, draft).then((next) => {
      setSettings(next);
      setDraft(next.values);
      onApplied(next.values);
      setState("saved");
      setMessage("Saved and applied to all connected clients.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to save settings");
    });
  };

  return (
    <PaneFrame
      className="maintenance-frame"
      header={<PaneHeader
        title="Maintenance"
        meta="Shared frontend runtime settings"
        actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={reload} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>}
      />}
    >
      <form className="maintenance-form" onSubmit={submit}>
        <div className="maintenance-intro">Changes are validated by the server, persisted for the next restart, and applied immediately to every connected client.</div>
        {settings?.sections.map((section) => (
          <section key={section.id} className="maintenance-section">
            <div className="maintenance-section-copy">
              <h2>{section.label}</h2>
              {section.description && <p>{section.description}</p>}
            </div>
            <div className="maintenance-table-wrap">
              <table className="maintenance-table">
                <thead><tr><th>Parameter</th><th>Value</th><th>Range</th><th>Apply</th></tr></thead>
                <tbody>
                  {section.settings.map((setting) => {
                    const value = draft?.[setting.key];
                    return (
                      <tr key={setting.key}>
                        <th scope="row"><span>{setting.label}</span>{setting.description && <small>{setting.description}</small>}</th>
                        <td>
                          {setting.type === "boolean" ? (
                            <button
                              type="button"
                              role="switch"
                              aria-checked={Boolean(value)}
                              className={`maintenance-switch ${value ? "is-on" : "is-off"}`}
                              disabled={!draft || state === "saving"}
                              onClick={() => setDraft((current) => current ? { ...current, [setting.key]: !current[setting.key] } : current)}
                            >
                              <span className="maintenance-switch-track" aria-hidden="true"><span className="maintenance-switch-thumb" /></span>
                              <span>{value ? "On" : "Off"}</span>
                            </button>
                          ) : setting.type === "select" ? (
                            <select value={String(value ?? "")} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)}>
                              {setting.options?.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}
                            </select>
                          ) : (
                            <input type="number" value={String(value ?? "")} min={setting.min} max={setting.max} step={setting.step ?? 1} disabled={!draft || state === "saving"} onChange={(event) => setDraft((current) => current ? { ...current, [setting.key]: Number(event.target.value) } : current)} />
                          )}
                          {setting.unit && <span className="maintenance-unit">{setting.unit}</span>}
                        </td>
