    async (request, reply) => {
      const interfaceId = Number(request.params.interfaceId);
      const windowSec = request.query.windowSec ? Number(request.query.windowSec) : undefined;
      if (!Number.isInteger(interfaceId)) return reply.code(400).send({ error: "invalid interface id" });
      const metrics = store.getInterfaceMetrics(interfaceId, Number.isFinite(windowSec) ? windowSec : undefined);
      if (!metrics) return reply.code(404).send({ error: "interface not found" });
      return metrics;
    }
  );

