  if (["RTP", "SRT"].includes(rule.proto.toUpperCase()) && hosts.length) throw new ProtocolMapValidationError(`row ${index + 1}: hosts are supported by HLS only`);
  if (rule.proto.toUpperCase() === "HLS" && endpoints.length && hosts.length) throw new ProtocolMapValidationError(`row ${index + 1}: choose an endpoint or host, not both`);
