  | { type: "stream:metrics"; streamKey: string; metrics: StreamMetricsResponse }
  | { type: "events:update"; events: EventLogItem[] }
  | { type: "config:update"; config: AppConfig };

export type AppConfig = {
  lostRetentionSec: number;
  historyWindowSec: number;
  staleAfterSec: number;
  diagnosticLog: boolean;
};

export type MaintenanceSetting = {
  key: keyof AppConfig;
  label: string;
  description?: string;
  type: "integer" | "select" | "boolean";
  unit?: string;
  min?: number;
  max?: number;
  step?: number;
  options?: Array<{ value: number; label: string }>;
  apply: "live" | "next-input" | "restart" | "manual";
};

export type MaintenanceSettingsResponse = {
  revision: number;
  sections: Array<{ id: string; label: string; description?: string; settings: MaintenanceSetting[] }>;
  values: AppConfig;
};

export type ProtocolRule = { enabled?: boolean; observe?: boolean; proto: "RTP" | "SRT" | "HLS"; endpoints?: string | string[]; hosts?: string | string[]; domains?: string | string[]; decode_as?: string | string[]; fec?: boolean; vlan?: number | string | null; stream_name?: string; };
export type ProtocolMapDocument = { observe_mode?: "all" | "configured_only" | "configured_plus_other"; protocols: ProtocolRule[]; };
export type ProtocolMapResponse = { revision: string; path: string; document: ProtocolMapDocument; apply: "restart_required"; };

export type BootstrapResponse = {
  streams: StreamListItem[];
  interfaces: InterfaceListItem[];
  timeline: TimelineRow[];
  summary: Summary;
  events: EventLogItem[];
};
.maintenance-frame {
  max-width: 1100px;
}

.maintenance-frame .pane-body {
  overflow: auto;
}

.maintenance-form {
  display: grid;
  gap: var(--space-4);
  padding: var(--space-3);
}

.maintenance-intro,
.maintenance-section {
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.maintenance-intro {
  padding: var(--space-3);
  color: var(--muted);
}

.maintenance-section-copy {
  padding: var(--space-3) var(--space-3) 0;
}

.maintenance-section-copy h2 {
  margin: 0;
  color: var(--text-strong);
  font-size: var(--font-size-md);
}

.maintenance-section-copy p {
  margin: var(--space-1) 0 0;
  color: var(--muted);
}

.maintenance-table-wrap {
  overflow-x: auto;
  padding: var(--space-3);
}

.maintenance-table {
  width: 100%;
  min-width: 660px;
  border-collapse: collapse;
}

.maintenance-table th,
.maintenance-table td {
  padding: var(--space-2);
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: middle;
}

.maintenance-table thead th {
  color: var(--muted);
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.maintenance-table tbody tr:last-child th,
.maintenance-table tbody tr:last-child td {
  border-bottom: 0;
}

.maintenance-table tbody th > span,
.maintenance-table tbody th > small {
  display: block;
}

.maintenance-table tbody th > span {
  color: var(--text-strong);
}

.maintenance-table tbody th > small {
  max-width: 460px;
  margin-top: 3px;
  color: var(--muted);
  font-size: var(--font-size-xs);
  font-weight: 400;
}

.maintenance-table input,
.maintenance-table select {
  width: 120px;
  min-height: var(--control-height);
  padding: 0 var(--space-2);
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--surface-muted);
  color: var(--text-strong);
}

.maintenance-unit {
  margin-left: var(--space-1);
  color: var(--muted);
}

.maintenance-apply {
  display: inline-flex;
  min-height: 22px;
  align-items: center;
  padding: 0 7px;
  border: 1px solid var(--success);
  border-radius: var(--radius-sm);
  background: var(--success-soft);
  color: var(--success);
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.maintenance-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}

.maintenance-message {
  color: var(--muted);
}

.maintenance-message-error {
  color: var(--danger);
}

.maintenance-message-saved {
  color: var(--success);
}

.maintenance-save-button,
.maintenance-secondary-button {
  min-height: var(--control-height);
  padding: 0 var(--space-3);
  border: 1px solid var(--accent-border);
  border-radius: var(--radius-sm);
  background: var(--accent);
  color: var(--text-inverse);
  cursor: pointer;
  font-weight: 700;
}

.maintenance-secondary-button {
  background: var(--surface-muted);
  color: var(--text);
}

.maintenance-save-button:disabled,
.maintenance-secondary-button:disabled {
  cursor: wait;
  opacity: .6;
}

.maintenance-switch {
  display: inline-flex;
  min-width: 76px;
  min-height: var(--control-height);
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 9px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  background: var(--surface-muted);
  color: var(--muted);
  cursor: pointer;
  font-size: var(--font-size-xs);
  font-weight: 700;
}

.maintenance-switch-track {
  display: inline-flex;
  width: 28px;
  height: 16px;
  align-items: center;
  padding: 2px;
  border-radius: 999px;
  background: var(--line-strong);
  transition: background-color .15s ease;
}

.maintenance-switch-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--surface);
  box-shadow: var(--shadow-sm);
  transition: transform .15s ease;
}

.maintenance-switch.is-on {
  border-color: var(--success);
  background: var(--success-soft);
  color: var(--success);
}

.maintenance-switch.is-on .maintenance-switch-track {
  background: var(--success);
}

.maintenance-switch.is-on .maintenance-switch-thumb {
  transform: translateX(12px);
}

.maintenance-switch:disabled {
  cursor: wait;
  opacity: .6;
}

.protocol-map-frame { max-width: 1500px; }
.protocol-map-controls, .protocol-map-row-actions { display: flex; flex-wrap: wrap; gap: var(--space-3); padding: var(--space-3); }
.protocol-map-controls label { display: grid; gap: var(--space-1); color: var(--muted); font-size: var(--font-size-xs); font-weight: 700; }
.protocol-map-controls input, .protocol-map-controls select { min-width: 250px; min-height: var(--control-height); padding: 0 var(--space-2); border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface-muted); color: var(--text-strong); }
.protocol-map-table { min-width: 1100px; }
.protocol-map-table input { width: 150px; }
.protocol-map-table td:nth-child(6) input { width: 86px; }
.protocol-map-table td:nth-child(7) input { width: 76px; margin-left: var(--space-1); }
.protocol-map-notice { padding: var(--space-3); border: 1px solid var(--warning); border-radius: var(--radius-md); background: var(--warning-soft); color: var(--warning); }
