const { readFile } = require("node:fs/promises");
const path = require("node:path");
const { AlertsSettings } = require("./fe/server/dist/alertsSettings.js");
(async () => {
  const root = process.env.TEST_ROOT;
  const settings = new AlertsSettings(path.join(root, "stm_config.json"));
  const first = await settings.get();
  if (!first.protocols.includes("HLS")) throw new Error("HLS protocol is missing");
  if (first.metrics.filter((metric) => metric.preview).length !== 8) throw new Error("preview metrics are missing");
  const second = await settings.update({ revision: first.revision, document: { ...first.document, _note: "alerts API verification" } });
  if (second.document._note !== "alerts API verification") throw new Error("updated document was not returned");
  const persisted = JSON.parse(await readFile(path.join(root, "alerts_config.json"), "utf8"));
  if (persisted._note !== "alerts API verification") throw new Error("document was not persisted");
  console.log("alerts settings temporary-file verification passed");
})().catch((error) => { console.error(error); process.exit(1); });
