type AlertRowProps = { index: number; row: AlertRule; metrics: AlertMetricDefinition[]; metricQuery: string; busy: boolean; onUpdate: (index: number, patch: Partial<AlertRule>) => void; onRemove: (index: number) => void };
function AlertRow({ index, row, metrics, metricQuery, busy, onUpdate, onRemove }: AlertRowProps) {
