  };
  return <tr><td>{index + 1}</td><td><button type="button" role="switch" aria-checked={row.enabled !== false} className={"maintenance-switch " + (row.enabled !== false ? "is-on" : "is-off")} disabled={busy} onClick={() => onUpdate(index, { enabled: row.enabled === false })}>{row.enabled === false ? "Off" : "On"}</button></td><td><input className="alerts-id-input" value={row.id} disabled={busy} onChange={(event) => onUpdate(index, { id: event.target.value })} /></td><td><select value={target} disabled={busy || row.proto === "RTP" || row.proto === "RTMP" || row.proto === "SRT" || row.proto === "HLS"} onChange={(event) => onUpdate(index, { target: event.target.value as AlertRule["target"], metric: "" })}><option value="flow">Flow</option><option value="stream">Stream</option><option value="interface">Interface</option><option value="any">Any</option></select></td><td><input className="alerts-metric-input" list={listId} value={row.metric} disabled={busy} onChange={(event) => onUpdate(index, { metric: event.target.value })} placeholder="Search metric" /><datalist id={listId}>{candidates.map((metric) => <option key={metric.key} value={metric.key} label={metric.description ?? metric.key} />)}</datalist>{selected && <small className="alerts-metric-detail">{selected.preview && <span className="alerts-preview">Preview</span>}{selected.unit ? selected.unit + " · " : ""}{selected.description}</small>}</td><td><select value={type} disabled={busy} onChange={(event) => changeType(event.target.value as AlertRule["type"])}><option value="threshold">Threshold</option><option value="counter_delta">Counter delta</option></select>{type === "threshold" && <select value={row.operator ?? ">"} disabled={busy} onChange={(event) => onUpdate(index, { operator: event.target.value as AlertRule["operator"] })}>{operators.map((operator) => <option key={operator} value={operator}>{operator}</option>)}</select>}</td><td><input type="number" value={String(type === "counter_delta" ? row.delta_threshold ?? "" : row.error_threshold ?? "")} disabled={busy} onChange={(event) => onUpdate(index, type === "counter_delta" ? { delta_threshold: numberOrUndefined(event.target.value) } : { error_threshold: numberOrUndefined(event.target.value) })} /></td><td>{type === "counter_delta" ? <label className="alerts-inline-field">after<input type="number" min="0" value={String(row.recover_after_sec ?? "")} disabled={busy} onChange={(event) => onUpdate(index, { recover_after_sec: numberOrUndefined(event.target.value) })} /><span>s</span></label> : <input type="number" value={String(row.recover_threshold ?? "")} disabled={busy} onChange={(event) => onUpdate(index, { recover_threshold: numberOrUndefined(event.target.value) })} />}</td><td><select value={row.severity ?? "warning"} disabled={busy} onChange={(event) => onUpdate(index, { severity: event.target.value })}>{severities.map((severity) => <option key={severity} value={severity}>{severity}</option>)}</select></td><td><button type="button" className="maintenance-secondary-button icon-only" disabled={busy} onClick={() => onRemove(index)} aria-label="Delete alert rule" title="Delete alert rule"><Icon name="delete" size={16} /></button></td></tr>;
}

function newRule(tab: Tab, rows: AlertRule[]): AlertRule {
  const prefix = tab === "general" ? "general" : tab.toLowerCase();
  const id = nextId(prefix + "_rule", rows);
  if (tab === "interface") return { id, enabled: true, target: "interface", metric: "rx.errors.window", type: "counter_delta", delta_threshold: 0, recover_after_sec: 3, severity: "warning" };
  if (tab === "HLS") return { id, enabled: false, target: "flow", proto: "HLS", metric: "hls.preview.http_5xx_count", type: "threshold", operator: ">", error_threshold: 0, recover_threshold: 0, severity: "warning" };
  if (tab === "RTP" || tab === "RTMP" || tab === "SRT") return { id, enabled: true, target: "flow", proto: tab, metric: "bitrate.bps", type: "threshold", operator: ">", error_threshold: 0, recover_threshold: 0, severity: "warning" };
