function nextId(prefix: string, rows: AlertRule[]) { let number = 1; while (rows.some((row) => row.id === prefix + "_" + number)) number += 1; return prefix + "_" + number; }
function ruleTab(rule: AlertRule): Tab { if (rule.target === "interface") return "interface"; if (rule.proto === "RTP" || rule.proto === "RTMP" || rule.proto === "SRT" || rule.proto === "HLS") return rule.proto; return "general"; }
function numberOrUndefined(value: string) { return value === "" ? undefined : Number(value); }
function matchesMetric(metric: AlertMetricDefinition, query: string) { const normalized = query.trim().toLowerCase(); return !normalized || [metric.key, metric.description, metric.unit].some((value) => value?.toLowerCase().includes(normalized)); }
function supportsMetric(metric: AlertMetricDefinition, target: string, proto: string | undefined) {
  if (target === "interface") return metric.key === "interval_sec" || metric.key.startsWith("link.") || metric.key.startsWith("rx.") || metric.key.startsWith("tx.");
  if (proto === "HLS") return metric.preview;
  if (proto === "RTP" || proto === "RTMP") return startsWithAny(metric.key, ["bitrate.", "packet_rate.", "packet_count.", "interval.", "jitter.", "clock_skew.", "seq_stats."]);
  if (proto === "SRT") return startsWithAny(metric.key, ["bitrate.", "packet_rate.", "packet_count.", "interval.", "packet_breakdown.", "control_type_count.", "seq_stats.", "rtt.", "rttvar.", "rate.", "rcvrate.", "bandwidth.", "nak_seqno."]);
  return startsWithAny(metric.key, ["bitrate.", "packet_rate.", "packet_count.", "duration."]);
}
function startsWithAny(value: string, prefixes: string[]) { return prefixes.some((prefix) => value.startsWith(prefix)); }
`;
