import { useEffect, useMemo, useState, type FormEvent } from "react";
import { getAlertsSettings, saveAlertsSettings } from "../api/client";
import type { AlertMetricDefinition, AlertRule, AlertsDocument, AlertsResponse } from "../types/api";
import { Icon } from "./ui/Icon";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

type Tab = "all" | "general" | "interface" | "RTP" | "RTMP" | "SRT" | "HLS";
type PaneState = "loading" | "idle" | "saving" | "saved" | "error";

const tabs: Array<{ key: Tab; label: string }> = [
  { key: "all", label: "All" },
  { key: "general", label: "General" },
  { key: "interface", label: "Interface" },
  { key: "RTP", label: "RTP" },
  { key: "RTMP", label: "RTMP" },
  { key: "SRT", label: "SRT" },
  { key: "HLS", label: "HLS" }
];
const operators = [">", ">=", "<", "<=", "==", "!="] as const;
const severities = ["info", "warning", "error", "critical"];

export function AlertsPane() {
  const [settings, setSettings] = useState<AlertsResponse | null>(null);
  const [rows, setRows] = useState<AlertRule[]>([]);
  const [tab, setTab] = useState<Tab>("all");
  const [metricQuery, setMetricQuery] = useState("");
  const [state, setState] = useState<PaneState>("loading");
  const [message, setMessage] = useState("");

  const load = () => {
    setState("loading");
    void getAlertsSettings().then((next) => {
      setSettings(next);
      setRows(next.document.alerts);
      setState("idle");
      setMessage("");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to load alerts settings");
    });
  };
  useEffect(load, []);

  const visibleRows = useMemo(() => rows.map((row, index) => ({ row, index })).filter(({ row }) => tab === "all" || ruleTab(row) === tab), [rows, tab]);
  const matchingMetrics = useMemo(() => (settings?.metrics ?? []).filter((metric) => supportsMetricForTab(metric, tab) && matchesMetric(metric, metricQuery)), [settings, tab, metricQuery]);
  const updateRow = (index: number, patch: Partial<AlertRule>) => setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, ...patch } : row));
  const removeRow = (index: number) => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index));
  const addRow = () => { if (tab !== "all") setRows((current) => [...current, newRule(tab, current)]); };

  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!settings) return;
    setState("saving");
    setMessage("");
    const document: AlertsDocument = { ...(settings.document._note ? { _note: settings.document._note } : {}), alerts: rows };
    void saveAlertsSettings(settings.revision, document).then((next) => {
      setSettings(next);
      setRows(next.document.alerts);
      setState("saved");
      setMessage("Saved. Restart STM to apply the new alert rules.");
    }).catch((error: unknown) => {
      setState("error");
      setMessage(error instanceof Error ? error.message : "Failed to apply alerts settings");
    });
  };

  return <PaneFrame className="maintenance-frame alerts-frame" header={<PaneHeader title="Alert rules" meta="STM thresholds and counter changes" actions={<button type="button" className="maintenance-secondary-button button-with-icon" onClick={load} disabled={state === "loading" || state === "saving"}><Icon name="reload" size={16} />Reload</button>} />}>
    <form className="maintenance-form" onSubmit={submit}>
      <div className="maintenance-intro">Rules are grouped by protocol. Metric candidates are filtered by the selected target and protocol; Apply writes <code>{settings?.path ?? "the configured alerts file"}</code>. Restart STM before the changes take effect.</div>
      <section className="maintenance-section alerts-toolbar">
        <div className="alerts-tabs" role="tablist" aria-label="Alert rule protocol">
          {tabs.map((item) => <button key={item.key} type="button" role="tab" aria-selected={tab === item.key} className={"alerts-tab" + (tab === item.key ? " is-active" : "")} onClick={() => setTab(item.key)}>{item.label}<span>{item.key === "all" ? rows.length : rows.filter((row) => ruleTab(row) === item.key).length}</span></button>)}
        </div>
        <label className="alerts-metric-search">Find metric candidates<input type="search" value={metricQuery} onChange={(event) => setMetricQuery(event.target.value)} placeholder="bitrate, rtt, packet…" /></label>
        <div className="alerts-metric-results" role="status">{metricQuery.trim() ? matchingMetrics.length ? <><strong>{matchingMetrics.length}</strong> matching candidate{matchingMetrics.length === 1 ? "" : "s"}: {matchingMetrics.slice(0, 8).map((metric) => <span key={metric.key} className="alerts-metric-chip" title={metricTooltip(metric)}>{metric.key}</span>)}{matchingMetrics.length > 8 && <span>…</span>}</> : "No matching candidates in this tab." : "Type to preview matching metric candidates."}</div>
      </section>
      {tab === "HLS" && <div className="protocol-map-notice">HLS candidates are preview-only. They are shown to confirm the future UI and are not emitted or evaluated by STM yet.</div>}
      <section className="maintenance-section"><div className="maintenance-table-wrap"><table className="maintenance-table alerts-table"><colgroup><col className="alerts-col-index" /><col className="alerts-col-enabled" /><col className="alerts-col-id" /><col className="alerts-col-target" /><col className="alerts-col-metric" /><col className="alerts-col-rule" /><col className="alerts-col-trigger" /><col className="alerts-col-recovery" /><col className="alerts-col-severity" /><col className="alerts-col-delete" /></colgroup><thead><tr><th>#</th><th>Enabled</th><th>Rule ID</th><th>Target</th><th>Metric</th><th>Rule</th><th>Trigger</th><th>Recovery</th><th>Severity</th><th /></tr></thead><tbody>
        {visibleRows.map(({ row, index }) => <AlertRow key={index} index={index} row={row} metrics={settings?.metrics ?? []} metricQuery={metricQuery} busy={state === "saving"} onUpdate={updateRow} onRemove={removeRow} />)}
        {visibleRows.length === 0 && <tr><td colSpan={10} className="alerts-empty">No {tab === "all" ? "alert" : tab} rules.{tab === "all" ? " Choose a protocol tab to add one." : " Add a rule to begin."}</td></tr>}
      </tbody></table></div><div className="protocol-map-row-actions">{tab !== "all" && <button type="button" className="maintenance-secondary-button button-with-icon" disabled={!settings || state === "saving"} onClick={addRow}><Icon name="add" size={16} />Add {tab === "general" ? "general" : tab} rule</button>}</div></section>
      <footer className="maintenance-actions"><span className={"maintenance-message maintenance-message-" + state} role="status">{state === "loading" ? "Loading alert rules…" : message}</span><button type="submit" className="maintenance-save-button button-with-icon" disabled={!settings || state === "loading" || state === "saving"}><Icon name="save" size={16} />{state === "saving" ? "Applying…" : "Apply"}</button></footer>
    </form>
  </PaneFrame>;
}

